595	    /**
596	     * The retention: the retention percentage of the amount before tax (the subtotal less the
597	     * discount), rounded down to the cent, and never more than the retention cap when there is one.
598	     * Tax is never held back, so the tax rate does not change it.
599	     */
600	    public BigDecimal retention(BigDecimal taxRate) {
601	        if (isCreditNote()) {
602	            return zero();
603	        }
604	        BigDecimal retention = subtotal().subtract(discount()).multiply(retentionPct).divide(BigDecimal.valueOf(100))
