617	    /** As {@link #retentionHeld}, but still what was held back when the invoice was written off. */
618	    private BigDecimal retentionKept(BigDecimal taxRate) {
619	        if (retentionReleasedOn != null && retentionReleasedAmount == null) {
620	            return zero();
621	        }
622	        BigDecimal cleared = retentionCredited == null ? BigDecimal.ZERO : retentionCredited;
623	        BigDecimal released = retentionReleasedAmount == null ? BigDecimal.ZERO : retentionReleasedAmount;
624	        return retention(taxRate).subtract(cleared).subtract(released).max(BigDecimal.ZERO)
625	                .setScale(scale(), RoundingMode.HALF_UP);
