628	    /**
629	     * How a credit note of the amount comes off this invoice once the given amount has been paid, at
630	     * the tax rate: first what it still owes, then the retention it holds back. The part taken off in
631	     * all, and of that the part clearing retention; the rest is left over as credit.
632	     */
633	    public BigDecimal[] creditTaken(BigDecimal amount, BigDecimal paid, BigDecimal taxRate) {
634	        if (hasPlan()) {
635	            // It comes off the plan's instalments to come instead (see #schedule).
636	            return new BigDecimal[] { amount, BigDecimal.ZERO };
637	        }
638	        BigDecimal toDue = amount.min(amountDue(paid, taxRate).max(BigDecimal.ZERO));
639	        BigDecimal toRetention = amount.subtract(toDue).min(retentionKept(taxRate));
640	        return new BigDecimal[] { toDue.add(toRetention), toRetention };
641	    }
