693	    /** The late fee's percentage of what is owed when it is charged. */
694	    private static final BigDecimal LATE_FEE_PCT = BigDecimal.valueOf(2);
695	
696	    /** The least late fee charged, in US dollars (before the cap). */
697	    private static final BigDecimal LATE_FEE_MIN_USD = BigDecimal.TEN;
