699	    /**
700	     * The late fee charged on what is unpaid when it is charged (before late charges), in the invoice's
701	     * currency: 2% of it rounded down to the cent, but at least $10.00 (see {@link #usdIn}), and never
702	     * more than the cap.
703	     */
704	    private BigDecimal lateFeeOn(BigDecimal unpaid, LocalDate on, BigDecimal cap) {
705	        BigDecimal pct = unpaid.max(BigDecimal.ZERO).multiply(LATE_FEE_PCT).divide(BigDecimal.valueOf(100))
706	                .setScale(scale(), RoundingMode.DOWN);
707	        return pct.max(usdIn(LATE_FEE_MIN_USD, on)).min(cap).max(zero());
708	    }
