710	    /**
711	     * An amount in US dollars in the invoice's currency: converted as a payment in another currency is,
712	     * through the workspace rate on the given day, worked out exactly and rounded down to the
713	     * currency's step.
714	     */
715	    private BigDecimal usdIn(BigDecimal usd, LocalDate on) {
716	        if (currency() == Currency.USD) {
717	            return usd.setScale(scale(), RoundingMode.HALF_UP);
718	        }
719	        return currency().divideDownToStep(usd, usdPerOn(on));
720	    }
