765	    /** The late interest charged on the invoice itself, released retention left out (see {@link #accrueLateInterest}). */
766	    private void accrueInvoiceInterest(List<Payment> payments, BigDecimal taxRate, BigDecimal annualRate,
767	            BigDecimal lateFeeUsd, LocalDate today) {
768	        if (status != InvoiceStatus.SENT || isCreditNote() || hasPlan() || dueDate == null
769	                || !today.isAfter(dueDate.plusDays(graceDays()))) {
770	            return;
771	        }
772	        boolean earnsInterest = annualRate != null && annualRate.signum() > 0;
773	        boolean chargesFee = lateFeeUsd != null && lateFeeUsd.signum() > 0;
774	        if (!earnsInterest && !chargesFee) {
775	            return;
776	        }
777	        record Part(LocalDate on, Long paymentId, BigDecimal amount, boolean credit) {
778	        }
779	        List<Part> inOrder = new ArrayList<>();
780	        payments.stream().filter(p -> !p.isReversed())
781	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
782	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount(), false)))
783	                .filter(p -> !p.on().isAfter(today))
784	                .forEach(inOrder::add);
785	        // What a credit note took off what the invoice owed counts only from its issue date: until then
786	        // the invoice still owed it. One issued during the grace period, or later than today, comes off
787	        // from the start.
788	        BigDecimal owed = payableBeforeInterest(taxRate).subtract(retentionReleased(taxRate));
789	        if (creditsOwedTaken != null && !creditsOwedTaken.isBlank()) {
790	            for (String credit : creditsOwedTaken.split(",")) {
791	                String[] parts = credit.split("=");
792	                LocalDate on = LocalDate.parse(parts[0].trim());
793	                BigDecimal amount = new BigDecimal(parts[1].trim());
794	                if (amount.signum() > 0 && on.isAfter(dueDate.plusDays(graceDays())) && !on.isAfter(today)) {
795	                    owed = owed.add(amount);
796	                    inOrder.add(new Part(on, Long.MIN_VALUE, amount, true));
797	                }
798	            }
799	        }
800	        inOrder.sort(Comparator.comparing(Part::on).thenComparing(Part::paymentId));
801	        BigDecimal paidInGrace = inOrder.stream().filter(p -> !p.on().isAfter(dueDate.plusDays(graceDays())))
802	                .map(Part::amount).reduce(BigDecimal.ZERO, BigDecimal::add);
803	        if (owed.subtract(paidInGrace).signum() <= 0) {
804	            return;
805	        }
806	        LocalDate overdueOn = dueDate.plusDays(graceDays() + 1);
807	        BigDecimal fee = chargesFee ? lateFeeOn(owed.subtract(paidInGrace), overdueOn, lateFeeCap(taxRate)) : zero();
808	        if (!earnsInterest && fee.signum() <= 0) {
809	            return;
810	        }
811	        BigDecimal daily = earnsInterest
812	                ? BigDecimal.ONE.add(annualRate.divide(BigDecimal.valueOf(36000), MathContext.DECIMAL128))
813	                : null;
814	        BigDecimal charged = BigDecimal.ZERO;
815	        BigDecimal unpaidInterest = BigDecimal.ZERO;
816	        BigDecimal unpaidFee = BigDecimal.ZERO;
817	        boolean feeCharged = false;
818	        LocalDate from = dueDate.plusDays(graceDays());
819	        LocalDate waiveOn = interestWaivedOn != null && !interestWaivedOn.isBefore(overdueOn)
820	                && !interestWaivedOn.isAfter(today) ? interestWaivedOn : null;
821	        BigDecimal feeWaived = BigDecimal.ZERO;
822	        BigDecimal interestWaived = BigDecimal.ZERO;
823	        for (Part part : inOrder) {
824	            if (waiveOn != null && part.on().isAfter(waiveOn)) {
825	                if (!feeCharged) {
826	                    unpaidFee = fee;
827	                    feeCharged = true;
828	                }
829	                if (earnsInterest && owed.signum() > 0) {
830	                    BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, waiveOn));
831	                    charged = charged.add(earned);
832	                    unpaidInterest = unpaidInterest.add(earned);
833	                }
834	                from = waiveOn;
835	                feeWaived = unpaidFee;
836	                interestWaived = unpaidInterest;
837	                unpaidFee = BigDecimal.ZERO;
838	                unpaidInterest = BigDecimal.ZERO;
839	                waiveOn = null;
840	            }
841	            if (!feeCharged && !part.on().isBefore(overdueOn)) {
842	                unpaidFee = fee;
843	                feeCharged = true;
844	            }
845	            if (earnsInterest && part.on().isAfter(from) && owed.signum() > 0) {
846	                BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, part.on()));
847	                charged = charged.add(earned);
848	                unpaidInterest = unpaidInterest.add(earned);
849	                from = part.on();
850	            }
851	            if (part.credit()) {
852	                owed = owed.subtract(part.amount());
853	                continue;
854	            }
855	            BigDecimal toOwed = part.amount().min(owed).max(BigDecimal.ZERO);
856	            BigDecimal rest = part.amount().subtract(toOwed);
857	            BigDecimal toFee = rest.min(unpaidFee).max(BigDecimal.ZERO);
858	            unpaidFee = unpaidFee.subtract(toFee);
859	            rest = rest.subtract(toFee);
860	            BigDecimal toInterest = rest.min(unpaidInterest).max(BigDecimal.ZERO);
861	            unpaidInterest = unpaidInterest.subtract(toInterest);
862	            owed = owed.subtract(toOwed).subtract(rest.subtract(toInterest));
863	        }
864	        if (waiveOn != null) {
865	            if (earnsInterest && owed.signum() > 0) {
866	                BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, waiveOn));
867	                charged = charged.add(earned);
868	                unpaidInterest = unpaidInterest.add(earned);
869	            }
870	            from = waiveOn;
871	            feeWaived = feeCharged ? unpaidFee : fee;
872	            interestWaived = unpaidInterest;
873	        }
874	        if (earnsInterest && owed.signum() > 0) {
875	            charged = charged.add(interestOn(owed, daily, ChronoUnit.DAYS.between(from, today)));
876	        }
877	        this.lateFee = fee.subtract(feeWaived);
878	        this.lateInterest = charged.subtract(interestWaived);
879	        this.lateWaived = feeWaived.add(interestWaived);
880	    }
