882	    /**
883	     * Works out the late interest released retention has been charged by the given day, at the annual
884	     * rate (a percentage), and adds it to the late interest. Payments, in the order they were made, pay
885	     * the rest of the invoice with its late fee and interest first; what is left of them pays the
886	     * released retention, then its interest earned so far. Released retention still unpaid more than
887	     * {@link #graceDays()} days after it falls due ({@link #retentionDueDate()}) earns interest by the
888	     * same rule as an invoice: from the end of its grace period, compounded daily at rate / 360
889	     * (Actual/360), with each payment after its grace period ending a period. Charges waived on a day
890	     * after the grace period ends are written off as for the invoice, and interest starts again from then.
891	     */
892	    private void accrueRetentionInterest(List<Payment> payments, BigDecimal taxRate, BigDecimal annualRate,
893	            LocalDate today) {
894	        LocalDate due = retentionDueDate();
895	        if (status != InvoiceStatus.SENT || isCreditNote() || hasPlan() || due == null
896	                || annualRate == null || annualRate.signum() <= 0 || !today.isAfter(due.plusDays(graceDays()))) {
897	            return;
898	        }
899	        BigDecimal released = retentionReleased(taxRate);
900	        if (released.signum() <= 0) {
901	            return;
902	        }
903	        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
904	        }
905	        List<Part> inOrder = payments.stream().filter(p -> !p.isReversed())
906	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
907	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
908	                .filter(p -> !p.on().isAfter(today))
909	                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
910	        // What the payments leave once the rest of the invoice, its fee and its interest are paid.
911	        BigDecimal ahead = payableBeforeInterest(taxRate).subtract(released).add(getLateFee()).add(getLateInterest());
912	        List<Part> toRetention = new ArrayList<>();
913	        for (Part part : inOrder) {
914	            BigDecimal toAhead = part.amount().min(ahead).max(BigDecimal.ZERO);
915	            ahead = ahead.subtract(toAhead);
916	            if (part.amount().subtract(toAhead).signum() > 0) {
917	                toRetention.add(new Part(part.on(), part.paymentId(), part.amount().subtract(toAhead)));
918	            }
919	        }
920	        LocalDate graceEnd = due.plusDays(graceDays());
921	        BigDecimal paidInGrace = toRetention.stream().filter(p -> !p.on().isAfter(graceEnd))
922	                .map(Part::amount).reduce(BigDecimal.ZERO, BigDecimal::add);
923	        if (released.subtract(paidInGrace).signum() <= 0) {
924	            return;
925	        }
926	        BigDecimal daily = BigDecimal.ONE.add(annualRate.divide(BigDecimal.valueOf(36000), MathContext.DECIMAL128));
927	        BigDecimal owed = released;
928	        BigDecimal charged = BigDecimal.ZERO;
929	        BigDecimal unpaidInterest = BigDecimal.ZERO;
930	        BigDecimal waived = BigDecimal.ZERO;
931	        LocalDate from = graceEnd;
932	        LocalDate waiveOn = interestWaivedOn != null && interestWaivedOn.isAfter(graceEnd)
933	                && !interestWaivedOn.isAfter(today) ? interestWaivedOn : null;
934	        for (Part part : toRetention) {
935	            if (waiveOn != null && part.on().isAfter(waiveOn)) {
936	                if (owed.signum() > 0) {
937	                    BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, waiveOn));
938	                    charged = charged.add(earned);
939	                    unpaidInterest = unpaidInterest.add(earned);
940	                }
941	                from = waiveOn;
942	                waived = unpaidInterest;
943	                unpaidInterest = BigDecimal.ZERO;
944	                waiveOn = null;
945	            }
946	            if (part.on().isAfter(from) && owed.signum() > 0) {
947	                BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, part.on()));
948	                charged = charged.add(earned);
949	                unpaidInterest = unpaidInterest.add(earned);
950	                from = part.on();
951	            }
952	            BigDecimal toOwed = part.amount().min(owed).max(BigDecimal.ZERO);
953	            BigDecimal rest = part.amount().subtract(toOwed);
954	            BigDecimal toInterest = rest.min(unpaidInterest).max(BigDecimal.ZERO);
955	            unpaidInterest = unpaidInterest.subtract(toInterest);
956	            owed = owed.subtract(toOwed).subtract(rest.subtract(toInterest));
957	        }
958	        if (waiveOn != null) {
959	            if (owed.signum() > 0) {
960	                BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, waiveOn));
961	                charged = charged.add(earned);
962	                unpaidInterest = unpaidInterest.add(earned);
963	            }
964	            from = waiveOn;
965	            waived = unpaidInterest;
966	        }
967	        if (owed.signum() > 0) {
968	            charged = charged.add(interestOn(owed, daily, ChronoUnit.DAYS.between(from, today)));
969	        }
970	        this.retentionInterest = charged.subtract(waived);
971	        this.lateInterest = this.lateInterest.add(retentionInterest);
972	        this.lateWaived = this.lateWaived.add(waived);
973	    }
