1221	    /**
1222	     * The plan's schedule at the tax rate, an ordinary loan of the grand total; empty when there is no
1223	     * plan. With the monthly rate i (the annual rate / 12 / 100) the instalment is P x i / (1 - (1 +
1224	     * i)^-n), or P / n at 0%, rounded up to the next whole unit of the currency. Each month's interest is the balance still
1225	     * owed x i, rounded half up to the cent, and its principal the instalment less the interest; the
1226	     * last instalment (or any earlier one the instalment would overpay) pays off the whole balance left
1227	     * plus its interest, so the schedule ends at zero. A plan with a down payment starts with it as
1228	     * instalment 0, due on the issue date with no interest, and the instalments are worked out on what
1229	     * is left. Instalment k falls due k months after the issue date, on the same day (the month's last day when
1230	     * it is shorter). Each credit note issued against it, in the order they were issued, then re-works
1231	     * the instalments due after its issue date by the same rule: from the principal still owed before
1232	     * them less what the credit note took off, over as many instalments, keeping their due dates; the
1233	     * instalments due before then stay as they were. A skipped instalment (never the last) pays only its
1234	     * interest, leaving the balance as it was, and the instalments after it are worked out again by the
1235	     * same rule from that balance over the instalments left, keeping their due dates.
1236	     */
1237	    public List<Instalment> schedule(BigDecimal taxRate) {
1238	        if (!hasPlan()) {
1239	            return List.of();
1240	        }
1241	        List<LocalDate> dues = new ArrayList<>(instalments + 1);
1242	        List<Instalment> schedule = new ArrayList<>();
1243	        BigDecimal principal = total(taxRate).setScale(scale(), RoundingMode.HALF_UP);
1244	        if (planDownPct.signum() > 0) {
1245	            BigDecimal down = downPayment(taxRate);
1246	            principal = principal.subtract(down);
1247	            dues.add(issueDate);
1248	            schedule.add(new Instalment(0, issueDate, down, zero(), down, principal));
1249	        }
1250	        int downs = dues.size();
1251	        for (int k = 1; k <= instalments; k++) {
1252	            dues.add(issueDate == null ? null : issueDate.plusMonths(k));
1253	        }
1254	        schedule.addAll(amortiseSkipping(principal, dues.subList(downs, dues.size()), 1));
1255	        if (creditsIssued != null && !creditsIssued.isBlank()) {
1256	            for (String credit : creditsIssued.split(",")) {
1257	                String[] parts = credit.split("=");
1258	                LocalDate on = LocalDate.parse(parts[0].trim());
1259	                int kept = Math.max(keptBefore(schedule, on), downs);
1260	                if (kept == schedule.size()) {
1261	                    continue;
1262	                }
1263	                BigDecimal left = principalBefore(schedule, kept, taxRate)
1264	                        .subtract(new BigDecimal(parts[1].trim()));
1265	                List<Instalment> reworked = amortiseSkipping(left, dues.subList(kept, dues.size()),
1266	                        schedule.get(kept).number());
1267	                schedule = new ArrayList<>(schedule.subList(0, kept));
1268	                schedule.addAll(reworked);
1269	            }
1270	        }
1271	        return schedule;
1272	    }
