1275	    private static int keptBefore(List<Instalment> schedule, LocalDate on) {
1276	        int kept = 0;
1277	        while (kept < schedule.size() && schedule.get(kept).dueDate() != null
1278	                && !schedule.get(kept).dueDate().isAfter(on)) {
1279	            kept++;
1280	        }
1281	        return kept;
