1300	     * {@link #amortise} the principal, then, when the skipped instalment is among them and not the last,
1301	     * make it pay only its interest and work out the instalments after it again (see {@link #schedule}).
1302	     */
1303	    private List<Instalment> amortiseSkipping(BigDecimal principal, List<LocalDate> dues, int firstNumber) {
1304	        List<Instalment> schedule = amortise(principal, dues, firstNumber);
1305	        int index = skippedInstalment == null ? -1 : skippedInstalment - firstNumber;
1306	        if (index < 0 || index >= schedule.size() - 1) {
1307	            return schedule;
1308	        }
1309	        BigDecimal balance = index == 0 ? principal.setScale(scale(), RoundingMode.HALF_UP)
1310	                : schedule.get(index - 1).balance();
1311	        BigDecimal interest = balance.multiply(instalmentRate.divide(BigDecimal.valueOf(1200), MathContext.DECIMAL128))
1312	                .setScale(scale(), RoundingMode.HALF_UP);
1313	        List<Instalment> skipped = new ArrayList<>(schedule.subList(0, index));
1314	        skipped.add(new Instalment(skippedInstalment, dues.get(index), interest, interest, zero(), balance));
1315	        skipped.addAll(amortise(balance, dues.subList(index + 1, dues.size()), skippedInstalment + 1));
1316	        return skipped;
1317	    }
