1319	    /**
1320	     * An ordinary loan of the principal at the plan's rate over one instalment per due date, numbered
1321	     * from the given number (see {@link #schedule}).
1322	     */
1323	    private List<Instalment> amortise(BigDecimal principal, List<LocalDate> dues, int firstNumber) {
1324	        MathContext mc = MathContext.DECIMAL128;
1325	        BigDecimal i = instalmentRate.divide(BigDecimal.valueOf(1200), mc);
1326	        int n = dues.size();
1327	        BigDecimal payment;
1328	        if (i.signum() == 0) {
1329	            payment = principal.divide(BigDecimal.valueOf(n), mc);
1330	        } else {
1331	            BigDecimal growth = BigDecimal.ONE.add(i).pow(n, mc);
1332	            payment = principal.multiply(i).multiply(growth).divide(growth.subtract(BigDecimal.ONE), mc);
1333	        }
1334	        payment = payment.setScale(0, RoundingMode.CEILING).setScale(scale());
1335	        List<Instalment> schedule = new ArrayList<>(n);
1336	        BigDecimal balance = principal.setScale(scale(), RoundingMode.HALF_UP);
1337	        for (int k = 1; k <= n; k++) {
1338	            BigDecimal interest = balance.multiply(i).setScale(scale(), RoundingMode.HALF_UP);
1339	            BigDecimal owed = balance.add(interest);
1340	            BigDecimal paid = k == n || payment.compareTo(owed) > 0 ? owed : payment;
1341	            BigDecimal repaid = paid.subtract(interest);
1342	            balance = balance.subtract(repaid);
1343	            schedule.add(new Instalment(firstNumber + k - 1, dues.get(k - 1), paid, interest, repaid, balance));
1344	        }
1345	        return schedule;
1346	    }
