1357	     * Each instalment of the plan at the tax rate once the given amount has been paid, on the given
1358	     * day: payments (with anything written off) pay the instalments in
1359	     * order, each itself, its late fee and then its late interest, each paid off before the next. An instalment not
1360	     * paid off more than {@link #graceDays()} days after its due date is overdue; empty when there is no
1361	     * plan.
1362	     */
1363	    public List<Instalment.Progress> instalmentProgress(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
1364	        List<Instalment.Progress> progress = new ArrayList<>();
1365	        BigDecimal left = paid.add(writtenOff(paid, taxRate)).add(getInterestSaved());
1366	        List<Instalment> schedule = schedule(taxRate);
1367	        for (int k = 0; k < schedule.size(); k++) {
1368	            Instalment instalment = schedule.get(k);
1369	            BigDecimal part = left.min(instalment.payment()).max(BigDecimal.ZERO).setScale(scale(), RoundingMode.HALF_UP);
1370	            left = left.subtract(part);
1371	            BigDecimal unpaid = instalment.payment().subtract(part);
1372	            BigDecimal fee = k < instalmentFees.size() ? instalmentFees.get(k) : zero();
1373	            BigDecimal toFee = left.min(fee).max(BigDecimal.ZERO).setScale(scale(), RoundingMode.HALF_UP);
1374	            left = left.subtract(toFee);
1375	            BigDecimal feeUnpaid = fee.subtract(toFee);
1376	            BigDecimal interest = k < instalmentInterest.size() ? instalmentInterest.get(k) : zero();
1377	            BigDecimal toInterest = left.min(interest).max(BigDecimal.ZERO).setScale(scale(), RoundingMode.HALF_UP);
1378	            left = left.subtract(toInterest);
1379	            BigDecimal interestUnpaid = interest.subtract(toInterest);
1380	            Instalment.Status status;
1381	            if (unpaid.signum() <= 0 && feeUnpaid.signum() <= 0 && interestUnpaid.signum() <= 0) {
1382	                status = Instalment.Status.PAID;
1383	            } else if (instalment.dueDate() != null && today.isAfter(instalment.dueDate().plusDays(graceDays()))) {
1384	                status = Instalment.Status.OVERDUE;
1385	            } else if (part.signum() > 0) {
1386	                status = Instalment.Status.PART_PAID;
1387	            } else {
1388	                status = Instalment.Status.DUE;
1389	            }
1390	            progress.add(new Instalment.Progress(instalment, part, unpaid, fee, feeUnpaid, interest,
1391	                    interestUnpaid, status));
1392	        }
1393	        return progress;
1394	    }
