1523	    /**
1524	     * As {@link #statusWhenPaid(BigDecimal, BigDecimal, LocalDate)}, but a fully paid invoice whose
1525	     * paid date (null when not known) is after its due date is paid late.
1526	     */
1527	    public InvoiceStatus statusWhenPaid(BigDecimal paid, LocalDate paidOn, BigDecimal taxRate, LocalDate today) {
1528	        if (status != InvoiceStatus.SENT) {
1529	            return status;
1530	        }
1531	        if (isWrittenOff()) {
1532	            return InvoiceStatus.WRITTEN_OFF;
1533	        }
1534	        BigDecimal amountDue = amountDue(paid, taxRate);
1535	        boolean due = amountDue.signum() > 0;
1536	        BigDecimal retentionDue = amountDue.min(retentionReleased(taxRate).add(getRetentionInterest())).max(BigDecimal.ZERO);
1537	        boolean restDue = amountDue.subtract(retentionDue).signum() > 0;
1538	        if (hasPlan()) {
1539	            if (due && instalmentProgress(paid, taxRate, today).stream()
1540	                    .anyMatch(p -> p.status() == Instalment.Status.OVERDUE)) {
1541	                return InvoiceStatus.OVERDUE;
1542	            }
1543	        } else if (restDue && dueDate != null && today.isAfter(dueDate.plusDays(graceDays()))) {
1544	            return InvoiceStatus.OVERDUE;
1545	        }
1546	        if (retentionDue.signum() > 0 && today.isAfter(retentionDueDate().plusDays(graceDays()))) {
1547	            return InvoiceStatus.OVERDUE;
1548	        }
1549	        if (!due && retentionHeld(taxRate).signum() > 0) {
1550	            return InvoiceStatus.RETENTION_HELD;
1551	        }
1552	        if (paid.signum() <= 0) {
1553	            return !due && getCredited().signum() > 0 ? InvoiceStatus.CREDITED : status;
1554	        }
1555	        if (due) {
1556	            return InvoiceStatus.PART_PAID;
1557	        }
1558	        List<Instalment> schedule = schedule(taxRate);
1559	        LocalDate finalDue = hasPlan() ? schedule.get(schedule.size() - 1).dueDate() : dueDate;
1560	        return paidOn != null && finalDue != null && paidOn.isAfter(finalDue) ? InvoiceStatus.PAID_LATE
1561	                : InvoiceStatus.PAID;
1562	    }
