1564	    /**
1565	     * The date the invoice was fully paid: the date of the payment that cleared its grand total at the
1566	     * tax rate, taking the parts of payments (not reversed) in the order they were applied (credit used
1567	     * counts on the day it was applied); null while something is still due or retention is held.
1568	     */
1569	    public LocalDate paidOn(List<Payment> payments, BigDecimal taxRate) {
1570	        BigDecimal total = payable(taxRate);
1571	        if (status != InvoiceStatus.SENT || isWrittenOff() || total.signum() <= 0 || retentionHeld(taxRate).signum() > 0) {
1572	            return null;
1573	        }
1574	        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
1575	        }
1576	        List<Part> inOrder = payments.stream().filter(p -> !p.isReversed())
1577	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
1578	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
1579	                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
1580	        BigDecimal sum = BigDecimal.ZERO;
1581	        for (Part p : inOrder) {
1582	            sum = sum.add(p.amount());
1583	            if (sum.signum() > 0 && isSmallEnoughToWriteOff(total.subtract(sum), p.on(), taxRate)) {
1584	                return p.on();
1585	            }
1586	        }
1587	        return null;
1588	    }
