1590	    /**
1591	     * What is still due once the given amount has been paid: the grand total less it, less what credit
1592	     * notes have credited, less the retention still held, less anything written off — so nothing once
1593	     * payments leave less than {@link #WRITE_OFF_LIMIT} that is no more than {@link #WRITE_OFF_SHARE}
1594	     * of the grand total. A credit note itself, and a written-off
1595	     * invoice, have nothing due.
1596	     */
1597	    public BigDecimal amountDue(BigDecimal paid, BigDecimal taxRate) {
1598	        if (isCreditNote() || isWrittenOff()) {
1599	            return zero();
1600	        }
1601	        return payable(taxRate).subtract(paid).subtract(writtenOff(paid, taxRate));
1602	    }
1603	
1604	    /**
1605	     * What is written off once the given amount has been paid: when payments leave less than
1606	     * {@link #WRITE_OFF_LIMIT} still due that is no more than {@link #WRITE_OFF_SHARE} of the grand
1607	     * total, all of what is left; otherwise nothing. Once the invoice is
1608	     * written off as a bad debt, everything it still owed then, late charges and retention included.
1609	     */
1610	    public BigDecimal writtenOff(BigDecimal paid, BigDecimal taxRate) {
1611	        if (isWrittenOff() && !isCreditNote()) {
1612	            return payable(taxRate).add(retentionKept(taxRate)).subtract(paid).max(BigDecimal.ZERO)
1613	                    .setScale(scale(), RoundingMode.HALF_UP);
1614	        }
1615	        BigDecimal left = payable(taxRate).subtract(paid);
1616	        return !isCreditNote() && paid.signum() > 0 && left.signum() > 0 && isSmallEnoughToWriteOff(left, taxRate)
1617	                ? left.setScale(scale(), RoundingMode.HALF_UP)
1618	                : zero();
1619	    }
