1621	    /** The least a part payment may be at the tax rate: {@link #MINIMUM_PART_SHARE} of the grand total. */
1622	    public BigDecimal minimumPart(BigDecimal taxRate) {
1623	        return total(taxRate).multiply(MINIMUM_PART_SHARE).setScale(scale(), RoundingMode.HALF_UP);
1624	    }
