1626	    /**
1627	     * Whether paying the amount on top of what was already paid is too small a part payment: under
1628	     * {@link #minimumPart} while leaving something still due (what would be written off counts as settled).
1629	     * For a plan the least is instead what is still unpaid on its earliest unpaid instalment.
1630	     */
1631	    public boolean isTooSmallPart(BigDecimal amount, BigDecimal paid, BigDecimal taxRate) {
1632	        if (hasPlan()) {
1633	            return amount.compareTo(earliestUnpaid(paid, taxRate)) < 0
1634	                    && amountDue(paid.add(amount), taxRate).signum() > 0;
1635	        }
1636	        return amount.compareTo(minimumPart(taxRate)) < 0 && amountDue(paid.add(amount), taxRate).signum() > 0;
1637	    }
