1689	    /**
1690	     * The sum of the line amounts, each after its own discount and already to the cent — so the subtotal
1691	     * matches what a client gets by adding up the lines shown.
1692	     */
1693	    public BigDecimal subtotal() {
1694	        return lines.stream().map(l -> l.amount(scale()))
1695	                .reduce(zero(), BigDecimal::add);
1696	    }
1697	
1698	    /**
1699	     * The amount taken off: the fixed amount when there is one (never more than the subtotal, should
1700	     * lines have been changed since), otherwise the discount percentage of the subtotal, rounded down
1701	     * to the cent. When there is a cap, it limits everything taken off — the line discounts plus
1702	     * this — so this shrinks to what the line discounts leave under the cap, never below zero.
1703	     */
1704	    public BigDecimal discount() {
1705	        BigDecimal discount = discountAmount.signum() > 0
1706	                ? discountAmount.min(subtotal()).setScale(scale(), RoundingMode.HALF_UP)
1707	                : subtotal().multiply(discountPct).divide(BigDecimal.valueOf(100)).setScale(scale(), RoundingMode.DOWN);
1708	        if (discountCap == null) {
1709	            return discount;
1710	        }
1711	        BigDecimal lineDiscounts = lines.stream().map(l -> l.discount(scale()))
1712	                .reduce(zero(), BigDecimal::add);
1713	        BigDecimal left = discountCap.setScale(scale(), RoundingMode.HALF_UP).subtract(lineDiscounts).max(zero());
1714	        return discount.min(left);
1715	    }
1716	
1717	    /**
1718	     * Each line's share of the discount, in the order of the lines. The discount's cents are split in
1719	     * proportion to the line amounts: each line first gets the whole cents of its exact share
1720	     * (rounded down), then the cents left over go one each to the lines with the largest leftover
1721	     * fractions; between equal fractions the cent goes to the line with the larger amount, and between
1722	     * equal amounts too to the lower line id. The shares add up to the discount.
1723	     */
1724	    public List<BigDecimal> discountShares() {
1725	        BigInteger discountCents = discount().movePointRight(scale()).toBigIntegerExact();
1726	        BigInteger subtotalCents = subtotal().movePointRight(scale()).toBigIntegerExact();
1727	        int n = lines.size();
1728	        BigInteger[] shares = new BigInteger[n];
1729	        BigInteger[] leftovers = new BigInteger[n];
1730	        BigInteger given = BigInteger.ZERO;
1731	        for (int i = 0; i < n; i++) {
1732	            if (subtotalCents.signum() == 0) {
1733	                shares[i] = BigInteger.ZERO;
1734	                leftovers[i] = BigInteger.ZERO;
1735	            } else {
1736	                // The exact share is discount * amount / subtotal; all fractions share the subtotal
1737	                // as denominator, so the remainders compare as the fractions do.
1738	                BigInteger[] qr = discountCents.multiply(lines.get(i).amount(scale()).movePointRight(scale()).toBigIntegerExact())
1739	                        .divideAndRemainder(subtotalCents);
1740	                shares[i] = qr[0];
1741	                leftovers[i] = qr[1];
1742	            }
1743	            given = given.add(shares[i]);
1744	        }
1745	        List<Integer> order = new ArrayList<>();
1746	        for (int i = 0; i < n; i++) {
1747	            order.add(i);
1748	        }
1749	        order.sort(Comparator.<Integer, BigInteger>comparing(i -> leftovers[i]).reversed()
1750	                .thenComparing(Comparator.<Integer, BigDecimal>comparing(i -> lines.get(i).amount(scale())).reversed())
1751	                .thenComparing(i -> lines.get(i).getId(), Comparator.nullsLast(Comparator.naturalOrder())));
1752	        int left = discountCents.subtract(given).intValueExact();
1753	        for (int k = 0; k < left; k++) {
1754	            int i = order.get(k);
1755	            shares[i] = shares[i].add(BigInteger.ONE);
1756	        }
1757	        List<BigDecimal> result = new ArrayList<>(n);
1758	        for (BigInteger share : shares) {
1759	            result.add(new BigDecimal(share, scale()));
1760	        }
1761	        return result;
1762	    }
1763	
1764	    /**
1765	     * Each line's exact tax, in the order of the lines: the line's own rate (a percentage), or the
1766	     * given workspace rate when it has none, on the line's amount less its share of the discount,
1767	     * unrounded. Tax-exempt lines, and every line of a tax-exempt client, have no tax.
1768	     */
1769	    private List<BigDecimal> exactLineTaxes(BigDecimal taxRate) {
1770	        List<BigDecimal> shares = discountShares();
1771	        List<BigDecimal> taxes = new ArrayList<>(lines.size());
1772	        for (int i = 0; i < lines.size(); i++) {
1773	            InvoiceLine line = lines.get(i);
1774	            taxes.add(clientTaxExempt || line.isTaxExempt() ? BigDecimal.ZERO
1775	                    : line.amount(scale()).subtract(shares.get(i)).multiply(line.taxRate(taxRate)).movePointLeft(2));
1776	        }
1777	        return taxes;
1778	    }
1779	
1780	    /**
1781	     * Each line's share of the invoice tax, in the order of the lines. The tax's cents are split in
1782	     * proportion to the lines' exact taxes as the discount is split: each line first gets the whole
1783	     * cents of its exact share (rounded down), then the cents left over go one each to the lines with
1784	     * the largest leftover fractions; between equal fractions the cent goes to the line with the
1785	     * larger exact tax, and between equal exact taxes too to the lower line id. The line taxes add up
1786	     * to the invoice tax.
1787	     */
1788	    public List<BigDecimal> lineTaxes(BigDecimal taxRate) {
1789	        List<BigDecimal> exact = exactLineTaxes(taxRate);
1790	        int n = lines.size();
1791	        BigInteger taxCents = roundTax(exact).movePointRight(scale()).toBigIntegerExact();
1792	        int common = exact.stream().mapToInt(BigDecimal::scale).max().orElse(0);
1793	        BigInteger[] weights = new BigInteger[n];
1794	        BigInteger total = BigInteger.ZERO;
1795	        for (int i = 0; i < n; i++) {
1796	            weights[i] = exact.get(i).setScale(common).unscaledValue();
1797	            total = total.add(weights[i]);
1798	        }
1799	        if (total.signum() < 0) {
1800	            // Split the magnitude, so the leftover cents are always added, then flip the shares back.
1801	            taxCents = taxCents.negate();
1802	            total = total.negate();
1803	            for (int i = 0; i < n; i++) {
1804	                weights[i] = weights[i].negate();
1805	            }
1806	        }
1807	        BigInteger[] shares = new BigInteger[n];
1808	        BigInteger[] leftovers = new BigInteger[n];
1809	        BigInteger given = BigInteger.ZERO;
1810	        for (int i = 0; i < n; i++) {
1811	            if (total.signum() == 0) {
1812	                shares[i] = BigInteger.ZERO;
1813	                leftovers[i] = BigInteger.ZERO;
1814	            } else {
1815	                // The exact share is tax * exact line tax / total exact tax; all fractions share the
1816	                // total as denominator, so the remainders compare as the fractions do.
1817	                BigInteger[] qr = taxCents.multiply(weights[i]).divideAndRemainder(total);
1818	                if (qr[1].signum() < 0) {
1819	                    qr[0] = qr[0].subtract(BigInteger.ONE);
1820	                    qr[1] = qr[1].add(total);
1821	                }
1822	                shares[i] = qr[0];
1823	                leftovers[i] = qr[1];
1824	            }
1825	            given = given.add(shares[i]);
1826	        }
1827	        List<Integer> order = new ArrayList<>();
1828	        for (int i = 0; i < n; i++) {
1829	            order.add(i);
1830	        }
1831	        order.sort(Comparator.<Integer, BigInteger>comparing(i -> leftovers[i]).reversed()
1832	                .thenComparing(Comparator.<Integer, BigInteger>comparing(i -> weights[i]).reversed())
1833	                .thenComparing(i -> lines.get(i).getId(), Comparator.nullsLast(Comparator.naturalOrder())));
1834	        int left = taxCents.subtract(given).intValueExact();
1835	        for (int k = 0; k < left; k++) {
1836	            int i = order.get(k);
1837	            shares[i] = shares[i].add(BigInteger.ONE);
1838	        }
1839	        boolean flipped = exact.stream().reduce(BigDecimal.ZERO, BigDecimal::add).signum() < 0;
1840	        List<BigDecimal> result = new ArrayList<>(n);
1841	        for (BigInteger share : shares) {
1842	            result.add(new BigDecimal(flipped ? share.negate() : share, scale()));
1843	        }
1844	        return result;
1845	    }
1846	
1847	    /** The sum of the exact line taxes, rounded once, half up to the cent. */
1848	    private BigDecimal roundTax(List<BigDecimal> exact) {
1849	        return exact.stream().reduce(BigDecimal.ZERO, BigDecimal::add).setScale(scale(), RoundingMode.HALF_UP);
1850	    }
1851	
1852	    /**
1853	     * The tax charged at the given rate (a percentage): every line's exact tax added up and rounded
1854	     * once, half up to the cent. It is what the line taxes add up to.
1855	     */
1856	    public BigDecimal tax(BigDecimal taxRate) {
1857	        return roundTax(exactLineTaxes(taxRate));
1858	    }
1859	
1860	    /** The grand total: the subtotal less the discount, plus tax at the given rate. */
1861	    public BigDecimal total(BigDecimal taxRate) {
1862	        return subtotal().subtract(discount()).add(tax(taxRate));
1863	    }
1864	}
