package net.officefloor.hq.app.invoices;


/**
 * One line of an invoice: a quantity (up to two decimals) times a unit price, less the line's own
 * percentage discount.
 */
@Entity
@Table(name = "invoice_line")
public class InvoiceLine {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String description;

    private BigDecimal qty;

    @Column(name = "unit_price")
    private BigDecimal unitPrice;

    /** Whether the line is left out of the taxed amount, e.g. postage. */
    @Column(name = "tax_exempt")
    private boolean taxExempt;

    /** The line's own percentage discount, 0 to 100 with up to two decimals; 0 is none. */
    @Column(name = "discount_pct")
    private BigDecimal discountPct = BigDecimal.ZERO;

    /** The line's own tax percentage, 0 to 100 with up to two decimals; null uses the workspace rate. */
    @Column(name = "tax_rate")
    private BigDecimal taxRate;

    /** The id of the invoice line this credit note line credits; null when it credits no line in particular. */
    @Column(name = "credit_of_line")
    private Long creditOfLine;

    protected InvoiceLine() {
    }

    public InvoiceLine(String description, BigDecimal qty, BigDecimal unitPrice, boolean taxExempt,
            BigDecimal discountPct, BigDecimal taxRate) {
        this.description = description;
        this.qty = qty;
        this.unitPrice = unitPrice;
        this.taxExempt = taxExempt;
        this.discountPct = discountPct;
        this.taxRate = taxRate;
    }

    /** A new line with the same description, quantity, price, discount, tax rate and exemption. */
    public InvoiceLine copy() {
        return new InvoiceLine(description, qty, unitPrice, taxExempt, discountPct, taxRate);
    }

    /** A new credit note line crediting this line, with its description, quantity, price, discount, tax rate and exemption. */
    public InvoiceLine creditCopy() {
        InvoiceLine credit = copy();
        credit.creditOfLine = id;
        return credit;
    }

    /** Changes the line's description, quantity, price, discount, tax rate and exemption; they have already been checked. */
    public void update(String description, BigDecimal qty, BigDecimal unitPrice, boolean taxExempt,
            BigDecimal discountPct, BigDecimal taxRate) {
        this.description = description;
        this.qty = qty;
        this.unitPrice = unitPrice;
        this.taxExempt = taxExempt;
        this.discountPct = discountPct;
        this.taxRate = taxRate;
    }

    public Long getId() {
        return id;
    }

    public String getDescription() {
        return description;
    }

    public BigDecimal getQty() {
        return qty;
    }

    public BigDecimal getUnitPrice() {
        return unitPrice;
    }

    public boolean isTaxExempt() {
        return taxExempt;
    }

    public BigDecimal getDiscountPct() {
        return discountPct;
    }

    public BigDecimal getTaxRate() {
        return taxRate;
    }

    public Long getCreditOfLine() {
        return creditOfLine;
    }

    /** The rate the line is taxed at: its own rate, or the given workspace rate when it has none. */
    public BigDecimal taxRate(BigDecimal workspaceRate) {
        return taxRate == null ? workspaceRate : taxRate;
    }

    /**
     * Quantity times unit price, rounded half up to the given number of decimals (2, the cent; 0 for
     * whole yen), before the line's discount.
     */
    public BigDecimal grossAmount(int scale) {
        return qty.multiply(unitPrice).setScale(scale, RoundingMode.HALF_UP);
    }

    /** The line's discount: its percentage of the gross amount, rounded down to the given number of decimals. */
    public BigDecimal discount(int scale) {
        return grossAmount(scale).multiply(discountPct).divide(BigDecimal.valueOf(100))
                .setScale(scale, RoundingMode.DOWN);
    }

    /** The line amount, to the given number of decimals: the gross amount less the line's discount. */
    public BigDecimal amount(int scale) {
        return grossAmount(scale).subtract(discount(scale));
    }
}
package net.officefloor.hq.app.invoices;


/** A payment received from a client on a date, allocated to its invoices. */
@Entity
@Table(name = "payment")
public class Payment {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "client_id")
    private Long clientId;

    private BigDecimal amount;

    @Column(name = "payment_date")
    private LocalDate date;

    /** The payment reference the client quoted, or null when none was. */
    private String reference;

    /** Whether the payment has been reversed (a bounced cheque): it then no longer counts. */
    private boolean reversed;

    /** The credit note whose rest this payment holds as credit; null for a payment from the client. */
    @Column(name = "credit_note")
    private Long creditNote;

    /** How much of the payment's unused credit has been refunded to the client; it is no longer credit. */
    private BigDecimal refunded = BigDecimal.ZERO;

    /** The currency the payment was paid in when not the client's own; null when it was the client's. */
    @Column(name = "paid_currency")
    private String paidCurrency;

    /** The amount paid in {@link #paidCurrency}; the amount is it converted into the client's currency. */
    @Column(name = "paid_amount")
    private BigDecimal paidAmount;

    @ElementCollection
    @CollectionTable(name = "payment_allocation", joinColumns = @JoinColumn(name = "payment_id"))
    private List<PaymentAllocation> allocations = new ArrayList<>();

    protected Payment() {
    }

    /**
     * A payment against one invoice, quoting the reference (null when none): the part applied to the
     * invoice, any rest of the amount held on the client's account as credit.
     */
    public static Payment against(Invoice invoice, BigDecimal amount, BigDecimal applied, LocalDate date,
            String reference) {
        Payment payment = new Payment();
        payment.clientId = invoice.getClientId();
        payment.amount = amount;
        payment.date = date;
        payment.reference = reference;
        payment.allocations.add(new PaymentAllocation(invoice.getId(), applied));
        return payment;
    }

    /**
     * A payment from the client spread over several of its invoices, quoting the reference (null when
     * none): each allocation is the part of the amount that goes to one invoice; any rest is held on
     * the client's account as credit.
     */
    public static Payment split(Long clientId, BigDecimal amount, LocalDate date, String reference,
            List<PaymentAllocation> allocations) {
        Payment payment = new Payment();
        payment.clientId = clientId;
        payment.amount = amount;
        payment.date = date;
        payment.reference = reference;
        payment.allocations.addAll(allocations);
        return payment;
    }

    /** A deposit: the whole amount held on the client's account as credit, applied to no invoice. */
    public static Payment deposit(Long clientId, BigDecimal amount, LocalDate date) {
        return deposit(clientId, amount, date, null);
    }

    /**
     * A deposit quoting the reference of one of the client's drafts (null when none): held for that
     * invoice while it is a draft.
     */
    public static Payment deposit(Long clientId, BigDecimal amount, LocalDate date, String reference) {
        Payment payment = new Payment();
        payment.clientId = clientId;
        payment.amount = amount;
        payment.date = date;
        payment.reference = reference;
        return payment;
    }

    /**
     * What is left of an issued credit note once its original has taken what it can: held on the
     * client's account as credit, dated the day the credit note was issued.
     */
    public static Payment fromCreditNote(Invoice note, BigDecimal amount) {
        Payment payment = deposit(note.getClientId(), amount, note.getIssueDate());
        payment.creditNote = note.getId();
        return payment;
    }

    /**
     * Notes that the payment was paid as the amount in the currency (null for the client's own, which
     * is then nothing to note); its amount is that converted into the client's currency.
     */
    public Payment paidIn(Currency currency, BigDecimal paid, Currency clientCurrency) {
        if (currency != null && currency != clientCurrency) {
            paidCurrency = currency.name();
            paidAmount = paid;
        }
        return this;
    }

    /** The currency the payment was paid in: the given client's currency unless it was paid in another. */
    public Currency paidCurrency(Currency clientCurrency) {
        return paidCurrency == null ? clientCurrency : Currency.orUsd(paidCurrency);
    }

    /** The amount paid, in the currency it was paid in. */
    public BigDecimal paidAmount() {
        return paidAmount == null ? amount : paidAmount;
    }

    /** The credit note whose rest this payment holds as credit; null for a payment from the client. */
    public Long getCreditNote() {
        return creditNote;
    }

    public Long getId() {
        return id;
    }

    public Long getClientId() {
        return clientId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public String getReference() {
        return reference;
    }

    public boolean isReversed() {
        return reversed;
    }

    /** Reverses the payment: it no longer counts on any invoice it was applied to. */
    public void reverse() {
        reversed = true;
    }

    public BigDecimal getRefunded() {
        return refunded;
    }

    /** Refunds part of this payment's unused credit to the client. */
    public void refund(BigDecimal part) {
        refunded = refunded.add(part);
    }

    public List<PaymentAllocation> getAllocations() {
        return allocations;
    }

    /**
     * The part of this payment applied to no invoice and not refunded: credit on the client's account;
     * none once reversed.
     */
    public BigDecimal credit() {
        if (reversed) {
            return BigDecimal.ZERO;
        }
        return amount.subtract(refunded).subtract(allocations.stream().map(PaymentAllocation::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add));
    }

    /** Applies part of this payment's credit to the invoice on the day. */
    public void apply(Long invoiceId, BigDecimal part, LocalDate on) {
        allocations.add(new PaymentAllocation(invoiceId, part, on));
    }

    /**
     * Whether every part of this payment that goes to the invoice is credit used on it (applied on its
     * own day), none of it recorded against it.
     */
    public boolean onlyCreditUsedOn(Long invoiceId) {
        return allocations.stream().filter(a -> a.getInvoiceId().equals(invoiceId)).allMatch(a -> a.getDate() != null);
    }

    /** Takes back every part of this payment applied to the invoice, as unused credit again; how much that was. */
    public BigDecimal returnCredit(Long invoiceId) {
        BigDecimal returned = amountTo(invoiceId);
        allocations.removeIf(a -> a.getInvoiceId().equals(invoiceId));
        return returned;
    }

    /** How much of this payment goes to the invoice. */
    public BigDecimal amountTo(Long invoiceId) {
        return allocations.stream().filter(a -> a.getInvoiceId().equals(invoiceId))
                .map(PaymentAllocation::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
package net.officefloor.hq.app.invoices;


/** The part of a payment that goes to one invoice. */
@Embeddable
public class PaymentAllocation {

    @Column(name = "invoice_id")
    private Long invoiceId;

    private BigDecimal amount;

    /** The day this part was applied, when later than the payment (credit used); null for the payment's date. */
    @Column(name = "applied_date")
    private LocalDate date;

    protected PaymentAllocation() {
    }

    /** A part of a payment applied on the given day rather than the day it was paid. */
    public PaymentAllocation(Long invoiceId, BigDecimal amount, LocalDate date) {
        this(invoiceId, amount);
        this.date = date;
    }

    public PaymentAllocation(Long invoiceId, BigDecimal amount) {
        this.invoiceId = invoiceId;
        this.amount = amount;
    }

    public Long getInvoiceId() {
        return invoiceId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    /** The day this part was applied, or null when on the payment's own date. */
    public LocalDate getDate() {
        return date;
    }
}
package net.officefloor.hq.app.clients;


/**
 * A currency a client is billed in, with the symbol its amounts are shown with and how many decimals
 * they have: yen have none, so every amount for a yen client is in whole yen.
 */
public enum Currency {
    USD("$", 2), EUR("€", 2), GBP("£", 2), JPY("¥", 0), CHF("CHF ", 2);

    private final String symbol;
    private final int scale;

    Currency(String symbol, int scale) {
        this.symbol = symbol;
        this.scale = scale;
    }

    /** How many decimals an amount has: 2 (to the cent), or 0 for yen. */
    public int scale() {
        return scale;
    }

    /** Whether the amount is whole in this currency: no more decimals than {@link #scale()}. */
    public boolean isWhole(BigDecimal amount) {
        return amount.stripTrailingZeros().scale() <= scale;
    }

    /** This currency's step: whole yen, 0.05 for Swiss francs, otherwise the cent. */
    public BigDecimal step() {
        return this == CHF ? new BigDecimal("0.05") : BigDecimal.ONE.movePointLeft(scale);
    }

    /**
     * The exact quotient amount / divisor rounded down (towards zero) to this currency's step, worked
     * out in decimals in one division so that a quotient landing on a step stays on it.
     */
    public BigDecimal divideDownToStep(BigDecimal amount, BigDecimal divisor) {
        BigDecimal step = step();
        return amount.divide(divisor.multiply(step), 0, RoundingMode.DOWN).multiply(step).setScale(scale);
    }

    /** The amount with its symbol and thousands separators, e.g. €1,234.50 or ¥1,235. */
    public String format(BigDecimal amount) {
        DecimalFormat number = new DecimalFormat(scale == 0 ? "#,##0" : "#,##0.00",
                DecimalFormatSymbols.getInstance(Locale.US));
        BigDecimal rounded = amount.setScale(scale, RoundingMode.HALF_UP);
        return (rounded.signum() < 0 ? "-" : "") + symbol + number.format(rounded.abs());
    }

    /** The currency with the code, or null when there is no such currency. */
    public static Currency of(String code) {
        for (Currency c : values()) {
            if (c.name().equals(code)) {
                return c;
            }
        }
        return null;
    }

    /** The currency with the code; US dollars when there is none. */
    public static Currency orUsd(String code) {
        Currency c = code == null ? null : of(code);
        return c == null ? USD : c;
    }
}
package net.officefloor.hq.app.invoices;

/**
 * Where an invoice is in its life: still being written, or sent to the client. A sent invoice is
 * part paid while some of it has been paid and some is still due, and paid once nothing is due, or
 * paid late when the payment that cleared it (taking payments in date order) came after its due date;
 * those follow from its payments and are never stored. A sent invoice with something still due
 * more than its client's grace period (a week unless set otherwise) after its due date is overdue, part paid or not; that follows from the date and is never stored.
 * An invoice spread over instalments is instead overdue when any of its instalments is not paid off a
 * grace period after that instalment's due date (payments pay the instalments in order).
 * A sent invoice with no payments can be voided: it is then void for good, owes nothing and takes no
 * payments or changes.
 * A credit note is a draft until it is issued, when it becomes CREDIT_NOTE for good. A sent invoice
 * whose issued credit notes leave nothing due, with nothing paid, is credited; that follows from its
 * credit notes and is never stored.
 * A sent invoice with retention still held back and nothing else due shows retention held instead of
 * paid; that follows from its retention and payments and is never stored.
 * A sent invoice written off as a bad debt is written off for good: it owes nothing, earns no more
 * interest and takes no payments; that follows from the day it was written off.
 */
public enum InvoiceStatus {
    DRAFT, SENT, PART_PAID, PAID, PAID_LATE, OVERDUE, VOID, CREDIT_NOTE, CREDITED, RETENTION_HELD, WRITTEN_OFF
}
package net.officefloor.hq.app;


/**
 * The workspace's late fee switch: the stored {@code late_fee} setting, an amount in US dollars such as
 * 25. With any fee set, a late fee of 2% of what is owed (at least $10.00) is charged once on an invoice
 * (on a plan, once on each instalment) when it becomes overdue, whatever amount the setting holds. With
 * no fee set none is charged, so it is 0.
 */
@Service
public class LateFee {

    static final String LATE_FEE = "late_fee";

    private final JdbcTemplate jdbc;

    public LateFee(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public BigDecimal usd() {
        List<String> fee = jdbc.queryForList("SELECT setting_value FROM app_setting WHERE name = ?",
                String.class, LATE_FEE);
        return fee.isEmpty() ? BigDecimal.ZERO : new BigDecimal(fee.get(0));
    }
}
package net.officefloor.hq.app;


/**
 * The workspace's tax rate: the stored {@code tax_rate} setting, a percentage such as 10. With no
 * rate set there is no tax, so the rate is 0.
 */
@Service
public class TaxRate {

    static final String TAX_RATE = "tax_rate";

    private final JdbcTemplate jdbc;

    public TaxRate(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public BigDecimal percent() {
        List<String> rate = jdbc.queryForList("SELECT setting_value FROM app_setting WHERE name = ?",
                String.class, TAX_RATE);
        return rate.isEmpty() ? BigDecimal.ZERO : new BigDecimal(rate.get(0));
    }
}
package net.officefloor.hq.app;


/**
 * The workspace's exchange rates: the US dollars one unit of each currency is worth, stored as the
 * {@code usd_per_<code>} settings. A US dollar is worth one; a currency with no rate set is taken
 * at par. Dated rates (the {@code fx_rate} table) take over from their date on: something converted on
 * a date uses the latest dated rate on or before it, or the standing rate before any. Invoices read
 * their client's rates themselves (see Invoice).
 */
@Service
public class ExchangeRates {

    /** The prefix of the setting holding a currency's rate, followed by its code (usd_per_EUR). */
    public static final String USD_PER = "usd_per_";

    private final JdbcTemplate jdbc;

    public ExchangeRates(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every rate set, by currency code. */
    public Map<String, BigDecimal> all() {
        Map<String, BigDecimal> rates = new LinkedHashMap<>();
        jdbc.queryForList("SELECT name, setting_value FROM app_setting WHERE name LIKE ? ORDER BY name", USD_PER + "%")
                .forEach(r -> rates.put(((String) r.get("NAME")).substring(USD_PER.length()),
                        new BigDecimal((String) r.get("SETTING_VALUE"))));
        return rates;
    }

    /** A dated rate: from the date on, the US dollars one unit of the currency is worth. */
    public record Dated(LocalDate from, Currency currency, BigDecimal usdPer) {
    }

    /** Every dated rate, by date then currency. */
    public List<Dated> dated() {
        return jdbc.query("SELECT from_date, currency, usd_per FROM fx_rate ORDER BY from_date, currency, id",
                (rs, n) -> new Dated(rs.getDate(1).toLocalDate(), Currency.of(rs.getString(2)), rs.getBigDecimal(3)));
    }

    /** Adds a dated rate. */
    public void addDated(LocalDate from, Currency currency, BigDecimal usdPer) {
        jdbc.update("INSERT INTO fx_rate (from_date, currency, usd_per) VALUES (?, ?, ?)", Date.valueOf(from),
                currency.name(), usdPer);
    }

    /**
     * The US dollars one unit of the currency is worth on the date: the latest dated rate on or before
     * it, otherwise the standing rate (see {@link #usdPer(Currency)}).
     */
    public BigDecimal usdPer(Currency currency, LocalDate on) {
        if (currency == Currency.USD) {
            return BigDecimal.ONE;
        }
        return jdbc.queryForList("SELECT usd_per FROM fx_rate WHERE currency = ? AND from_date <= ? ORDER BY from_date DESC, id DESC LIMIT 1",
                BigDecimal.class, currency.name(), Date.valueOf(on)).stream().findFirst().orElseGet(() -> usdPer(currency));
    }

    /** The US dollars one unit of the currency is worth: one for the dollar or a currency with no rate set. */
    public BigDecimal usdPer(Currency currency) {
        if (currency == Currency.USD) {
            return BigDecimal.ONE;
        }
        return jdbc.queryForList("SELECT setting_value FROM app_setting WHERE name = ?", String.class, USD_PER + currency.name())
                .stream().findFirst().map(v -> new BigDecimal(v.trim())).orElse(BigDecimal.ONE);
    }

    /**
     * The amount paid in one currency converted into another through US dollars: amount x (dollars per
     * unit paid) / (dollars per unit of the other), at the rates in force on the date, worked out exactly
     * and rounded down to the other's step, so the client is never credited more than was received.
     */
    public BigDecimal convert(BigDecimal amount, Currency from, Currency to, LocalDate on) {
        if (from == to) {
            return amount.setScale(to.scale());
        }
        return to.divideDownToStep(amount.multiply(usdPer(from, on)), usdPer(to, on));
    }
}

