/**
 * A currency a client is billed in, with the symbol its amounts are shown with and how many decimals
 * they have: yen have none, so every amount for a yen client is in whole yen.
 */
public enum Currency {
    USD("$", 2), EUR("€", 2), GBP("£", 2), JPY("¥", 0), CHF("CHF ", 2);

    private final String symbol;
    private final int scale;

    Currency(String symbol, int scale) {
        this.symbol = symbol;
        this.scale = scale;
    }

    /** How many decimals an amount has: 2 (to the cent), or 0 for yen. */
    public int scale() {
        return scale;
    }

    /** Whether the amount is whole in this currency: no more decimals than {@link #scale()}. */
    public boolean isWhole(BigDecimal amount) {
        return amount.stripTrailingZeros().scale() <= scale;
    }

    /** This currency's step: whole yen, 0.05 for Swiss francs, otherwise the cent. */
    public BigDecimal step() {
        return this == CHF ? new BigDecimal("0.05") : BigDecimal.ONE.movePointLeft(scale);
    }

    /**
     * The exact quotient amount / divisor rounded down (towards zero) to this currency's step, worked
     * out in decimals in one division so that a quotient landing on a step stays on it.
     */
    public BigDecimal divideDownToStep(BigDecimal amount, BigDecimal divisor) {
        BigDecimal step = step();
        return amount.divide(divisor.multiply(step), 0, RoundingMode.DOWN).multiply(step).setScale(scale);
    }

    /** The amount with its symbol and thousands separators, e.g. €1,234.50 or ¥1,235. */
    public String format(BigDecimal amount) {
        DecimalFormat number = new DecimalFormat(scale == 0 ? "#,##0" : "#,##0.00",
                DecimalFormatSymbols.getInstance(Locale.US));
        BigDecimal rounded = amount.setScale(scale, RoundingMode.HALF_UP);
        return (rounded.signum() < 0 ? "-" : "") + symbol + number.format(rounded.abs());
    }

    /** The currency with the code, or null when there is no such currency. */
    public static Currency of(String code) {
        for (Currency c : values()) {
            if (c.name().equals(code)) {
                return c;
            }
        }
        return null;
    }

    /** The currency with the code; US dollars when there is none. */
    public static Currency orUsd(String code) {
        Currency c = code == null ? null : of(code);
        return c == null ? USD : c;
    }
}
package net.officefloor.hq.app.invoices;

/**
 * Where an invoice is in its life: still being written, or sent to the client. A sent invoice is
 * part paid while some of it has been paid and some is still due, and paid once nothing is due, or
 * paid late when the payment that cleared it (taking payments in date order) came after its due date;
 * those follow from its payments and are never stored. A sent invoice with something still due
 * more than its client's grace period (a week unless set otherwise) after its due date is overdue, part paid or not; that follows from the date and is never stored.
 * An invoice spread over instalments is instead overdue when any of its instalments is not paid off a
 * grace period after that instalment's due date (payments pay the instalments in order).
 * A sent invoice with no payments can be voided: it is then void for good, owes nothing and takes no
 * payments or changes.
 * A credit note is a draft until it is issued, when it becomes CREDIT_NOTE for good. A sent invoice
 * whose issued credit notes leave nothing due, with nothing paid, is credited; that follows from its
 * credit notes and is never stored.
 * A sent invoice with retention still held back and nothing else due shows retention held instead of
 * paid; that follows from its retention and payments and is never stored.
 * A sent invoice written off as a bad debt is written off for good: it owes nothing, earns no more
 * interest and takes no payments; that follows from the day it was written off.
 */
public enum InvoiceStatus {
    DRAFT, SENT, PART_PAID, PAID, PAID_LATE, OVERDUE, VOID, CREDIT_NOTE, CREDITED, RETENTION_HELD, WRITTEN_OFF
}
