188	    /**
189	     * An invoice for a client with payment terms is due that many days after it is issued; otherwise
190	     * as {@link #dueDateFor(LocalDate)}.
191	     */
192	    private LocalDate dueDateFor(Long clientId, LocalDate issued) {
193	        return clients.findById(clientId)
194	                .map(Client::getTermsDays)
195	                .map(days -> issued.plusDays(days))
196	                .orElseGet(() -> dueDateFor(issued));
197	    }
