199	    /** A new invoice is due on the last day of the month after the month it is issued in. */
200	    static LocalDate dueDateFor(LocalDate issued) {
201	        LocalDate nextMonth = issued.plusMonths(1);
202	        return nextMonth.withDayOfMonth(nextMonth.lengthOfMonth());
203	    }
