206	     * Adds a line to an invoice; empty if no such invoice. The line has already been checked. A sent
207	     * invoice with no payments goes back to draft; one with a payment refuses it.
208	     */
209	    @Transactional
210	    public Optional<Invoice> addLine(Long invoiceId, String description, BigDecimal qty, BigDecimal unitPrice,
211	            boolean taxExempt, BigDecimal discountPct, BigDecimal taxRate) {
212	        Optional<Invoice> found = load(invoiceId);
