214	            requireWhole(invoice.currency(), unitPrice, "The unit price");
215	            boolean reopened = reopenForChange(invoice, "A paid invoice cannot take new lines.");
216	            invoice.addLine(new InvoiceLine(description, qty, unitPrice, taxExempt, discountPct, taxRate));
217	            invoices.saveAndFlush(invoice);
