276	     * Gives an invoice a percentage discount, or a fixed amount off when one is given; the one given
277	     * clears the other, and the cap (null for none) limits everything taken off, line discounts included. Empty if no such invoice. The values have already been checked; a fixed amount
278	     * over the subtotal is refused, as is a discount taking off more than a fifth of the subtotal
279	     * (after the cap) without a reason. A sent invoice with no payments goes back to draft; one with a
280	     * payment refuses it.
281	     */
282	    @Transactional
283	    public Optional<Invoice> setDiscount(Long invoiceId, BigDecimal discountPct, BigDecimal discountAmount,
284	            BigDecimal discountCap, String discountReason) {
285	        Optional<Invoice> found = load(invoiceId);
286	        found.ifPresent(invoice -> {
287	            if (invoice.isCreditNote()) {
288	                throw new InvoiceRejectedException("A credit note has no discount.");
289	            }
290	            if (discountAmount != null) {
291	                requireWhole(invoice.currency(), discountAmount, "The discount amount");
292	            }
293	            if (discountCap != null) {
294	                requireWhole(invoice.currency(), discountCap, "The discount cap");
295	            }
296	            boolean reopened = reopenForChange(invoice, "A paid invoice cannot be given a discount.");
297	            if (discountAmount != null) {
