302	            invoice.setDiscountCap(discountCap);
303	            invoice.setDiscountReason(discountReason);
304	            if (invoice.discountLacksReason()) {
305	                throw new InvoiceRejectedException(
306	                        "A discount of more than 20% of the subtotal needs a reason.");
307	            }
308	            invoices.saveAndFlush(invoice);
309	            if (reopened) {
310	                audit.record("INVOICE_REOPENED id=" + invoice.getId());
311	            }
312	        });
