334	    /**
335	     * Sets the percentage of a draft's amount before tax held back as retention, and the most it holds
336	     * back (null for no cap); empty if no such invoice.
337	     * The percentage has already been checked; any invoice that is not a draft, or a credit note, is refused.
338	     */
339	    @Transactional
340	    public Optional<Invoice> setRetention(Long invoiceId, BigDecimal retentionPct, BigDecimal retentionCap) {
341	        Optional<Invoice> found = load(invoiceId);
342	        found.ifPresent(invoice -> {
343	            if (invoice.isCreditNote()) {
344	                throw new InvoiceRejectedException("A credit note holds back no retention.");
345	            }
346	            if (!invoice.isDraft()) {
347	                throw new InvoiceRejectedException("Retention can only be set on a draft.");
348	            }
349	            if (invoice.hasPlan() && retentionPct.signum() > 0) {
350	                throw new InvoiceRejectedException("An invoice spread over instalments cannot also hold back retention.");
351	            }
352	            if (retentionCap != null) {
353	                requireWhole(invoice.currency(), retentionCap, "The retention cap");
354	            }
355	            invoice.setRetentionPct(retentionPct);
356	            invoice.setRetentionCap(retentionCap);
357	            invoices.saveAndFlush(invoice);
358	        });
359	        return found;
