362	    /**
363	     * Spreads a draft over the number of monthly instalments at the annual interest rate, after a down
364	     * payment of the percentage of the grand total; empty if no
365	     * such invoice. Both have already been checked; any invoice that is not a draft, a credit note, or
366	     * one holding back retention is refused, as is a plan whose monthly instalment would be worth less
367	     * than {@link Invoice#MIN_INSTALMENT_USD} US dollars at today's rates.
368	     */
369	    @Transactional
370	    public Optional<Invoice> setPlan(Long invoiceId, int instalments, BigDecimal instalmentRate,
371	            BigDecimal planDownPct) {
372	        Optional<Invoice> found = load(invoiceId);
373	        found.ifPresent(invoice -> {
374	            if (invoice.isCreditNote()) {
375	                throw new InvoiceRejectedException("A credit note cannot be spread over instalments.");
376	            }
377	            if (!invoice.isDraft()) {
378	                throw new InvoiceRejectedException("Only a draft can be spread over instalments.");
379	            }
380	            if (invoice.getRetentionPct().signum() > 0) {
381	                throw new InvoiceRejectedException("An invoice holding back retention cannot also be spread over instalments.");
382	            }
383	            invoice.setPlan(instalments, instalmentRate, planDownPct);
384	            if (invoice.isInstalmentTooSmall(taxRate.percent(), today.date())) {
385	                throw new InvoiceRejectedException("The monthly instalment must be worth at least $"
386	                        + Invoice.MIN_INSTALMENT_USD.toPlainString() + " at today's exchange rates.");
387	            }
388	            invoices.saveAndFlush(invoice);
389	        });
390	        return found;
391	    }
