393	    /**
394	     * Releases the given amount of the retention held back on a sent invoice today (all that is still
395	     * held when it is null), adding it to the amount due (all that is released falling due
396	     * {@link Invoice#RETENTION_DUE_DAYS} days after the latest release), and records the amount
397	     * released in the audit; empty if no such invoice. Refused while anything other than retention
398	     * already released is still due, when there is no retention held to release, or when the amount is
399	     * more than is held.
400	     */
401	    @Transactional
402	    public Optional<Invoice> releaseRetention(Long invoiceId, BigDecimal amount) {
403	        Optional<Invoice> found = load(invoiceId);
404	        found.ifPresent(invoice -> {
405	            if (invoice.isDraft() || invoice.isVoid() || invoice.isCreditNote()) {
406	                throw new InvoiceRejectedException("Retention can only be released on a sent invoice.");
407	            }
408	            if (invoice.isWrittenOff()) {
409	                throw new InvoiceRejectedException("The retention was written off with the invoice.");
410	            }
411	            BigDecimal rate = taxRate.percent();
412	            BigDecimal held = invoice.retentionHeld(rate);
413	            if (held.signum() <= 0) {
414	                throw new InvoiceRejectedException("There is no retention held to release.");
415	            }
416	            BigDecimal release = amount == null ? held
417	                    : amount.setScale(invoice.currency().scale(), RoundingMode.HALF_UP);
418	            if (amount != null) {
419	                requireWhole(invoice.currency(), amount, "The amount to release");
420	                if (amount.signum() <= 0) {
421	                    throw new InvoiceRejectedException("The amount to release must be more than zero.");
422	                }
423	                if (amount.compareTo(held) > 0) {
424	                    throw new InvoiceRejectedException("The amount to release cannot be more than the "
425	                            + invoice.currency().format(held) + " still held.");
426	                }
427	            }
428	            BigDecimal due = invoice.amountDue(paid(List.of(invoice)).get(invoice.getId()), rate);
429	            BigDecimal elseDue = due.subtract(due.min(invoice.retentionReleased(rate).add(invoice.getRetentionInterest())).max(BigDecimal.ZERO));
430	            if (elseDue.signum() > 0) {
431	                throw new InvoiceRejectedException("The retention can only be released once nothing else is due; "
432	                        + invoice.currency().format(elseDue) + " is still due.");
433	            }
434	            invoice.releaseRetention(today.date(), release);
435	            invoices.saveAndFlush(invoice);
436	            audit.record("RETENTION_RELEASED id=" + invoice.getId() + " amount=" + release.toPlainString());
437	        });
438	        return found;
439	    }
