441	    /**
442	     * Waives the late fee and late interest still unpaid on a sent invoice today, writing them off, and
443	     * records what was waived in the audit; empty if no such invoice. Interest starts again from today on
444	     * what is still owed, with no new fee. Refused when there is nothing to waive.
445	     */
446	    @Transactional
447	    public Optional<Invoice> waiveInterest(Long invoiceId) {
448	        Optional<Invoice> found = load(invoiceId);
449	        found.ifPresent(invoice -> {
450	            if (invoice.isWrittenOff()) {
451	                throw new InvoiceRejectedException("The late charges were written off with the invoice.");
452	            }
453	            BigDecimal before = invoice.getLateWaived();
454	            invoice.waiveInterest(today.date());
455	            withInterest(List.of(invoice));
456	            BigDecimal waived = invoice.getLateWaived().subtract(before);
457	            if (invoice.hasPlan() || waived.signum() <= 0) {
458	                throw new InvoiceRejectedException("There is no unpaid late interest or late fee to waive.");
459	            }
460	            invoices.saveAndFlush(invoice);
461	            audit.record("INTEREST_WAIVED id=" + invoice.getId() + " amount=" + waived.toPlainString());
462	        });
463	        return found;
464	    }
