466	    /**
467	     * Skips an instalment of a sent invoice's plan: it pays only its interest, and the instalments after
468	     * it are worked out again on the balance still owed (see {@link Invoice#schedule}); records it in the
469	     * audit; empty if no such invoice. An instalment that is overdue, paid (even in part) or the last is
470	     * refused, as is skipping a second one.
471	     */
472	    @Transactional
473	    public Optional<Invoice> skipInstalment(Long invoiceId, int number) {
474	        Optional<Invoice> found = load(invoiceId);
475	        found.ifPresent(invoice -> {
476	            if (!invoice.hasPlan() || invoice.isDraft() || invoice.isVoid() || invoice.isCreditNote()
477	                    || invoice.isWrittenOff()) {
478	                throw new InvoiceRejectedException("Only an instalment of a sent plan can be skipped.");
479	            }
480	            BigDecimal rate = taxRate.percent();
481	            BigDecimal paid = paid(List.of(invoice)).get(invoice.getId());
482	            List<Instalment.Progress> progress = invoice.instalmentProgress(paid, rate, today.date());
483	            Instalment.Progress instalment = progress.stream().filter(p -> p.instalment().number() == number)
484	                    .findFirst().orElseThrow(() -> new InvoiceRejectedException("There is no such instalment to skip."));
485	            if (number < 1) {
486	                throw new InvoiceRejectedException("The down payment cannot be skipped.");
487	            }
488	            if (instalment == progress.get(progress.size() - 1)) {
489	                throw new InvoiceRejectedException("The last instalment cannot be skipped.");
490	            }
491	            if (instalment.status() == Instalment.Status.OVERDUE) {
492	                throw new InvoiceRejectedException("An overdue instalment cannot be skipped.");
493	            }
494	            if (instalment.paid().signum() > 0) {
495	                throw new InvoiceRejectedException("An instalment already paid cannot be skipped.");
496	            }
497	            if (invoice.getSkippedInstalment() != null) {
498	                throw new InvoiceRejectedException("This plan has already skipped an instalment.");
499	            }
500	            invoice.skipInstalment(number);
501	            invoices.saveAndFlush(invoice);
502	            withInterest(List.of(invoice));
503	            audit.record("INSTALMENT_SKIPPED id=" + invoice.getId() + " instalment=" + number);
504	        });
505	        return found;
506	    }
