508	    /**
509	     * Writes off a sent invoice that still has something owed as a bad debt today: everything still
510	     * owed on it, late charges and retention included, and records what was written off in the audit;
511	     * empty if no such invoice. It then owes nothing, earns no more interest and takes no payments. A
512	     * draft, a void invoice, a credit note, one already written off or one with nothing owed is refused.
513	     */
514	    @Transactional
515	    public Optional<Invoice> writeOff(Long invoiceId) {
516	        Optional<Invoice> found = load(invoiceId);
517	        found.ifPresent(invoice -> {
518	            if (invoice.isDraft()) {
519	                throw new InvoiceRejectedException("A draft cannot be written off; only a sent invoice can.");
520	            }
521	            if (invoice.isVoid()) {
522	                throw new InvoiceRejectedException("A void invoice cannot be written off.");
523	            }
524	            if (invoice.isCreditNote()) {
525	                throw new InvoiceRejectedException("A credit note cannot be written off.");
526	            }
527	            if (invoice.isWrittenOff()) {
528	                throw new InvoiceRejectedException("This invoice has already been written off.");
529	            }
530	            BigDecimal rate = taxRate.percent();
531	            BigDecimal paid = paid(List.of(invoice)).get(invoice.getId());
532	            if (invoice.amountDue(paid, rate).add(invoice.retentionHeld(rate)).signum() <= 0) {
533	                throw new InvoiceRejectedException("There is nothing owed on this invoice to write off.");
534	            }
535	            invoice.writeOff(today.date());
536	            withInterest(List.of(invoice));
537	            BigDecimal amount = invoice.writtenOff(paid, rate);
538	            invoices.saveAndFlush(invoice);
539	            audit.record("INVOICE_WRITTEN_OFF id=" + invoice.getId() + " amount=" + amount.toPlainString());
540	        });
541	        return found;
542	    }
