544	    /**
545	     * Readies the invoice for a change: a draft stays as it is; a sent invoice with no payments goes
546	     * back to draft, to be sent again; an invoice with any payment is refused with the message.
547	     * Whether it went back to draft.
548	     */
549	    private boolean reopenForChange(Invoice invoice, String refusal) {
550	        if (invoice.isDraft()) {
551	            return false;
552	        }
553	        if (invoice.isVoid()) {
554	            throw new InvoiceRejectedException("A void invoice cannot be changed.");
555	        }
556	        if (invoice.isCreditNote()) {
557	            throw new InvoiceRejectedException("An issued credit note cannot be changed.");
558	        }
559	        if (invoice.isWrittenOff()) {
560	            throw new InvoiceRejectedException("A written-off invoice cannot be changed.");
561	        }
562	        if (invoice.hasCreditNotesIssued()) {
563	            throw new InvoiceRejectedException("An invoice with an issued credit note cannot be changed.");
564	        }
565	        if (!payments.findForInvoice(invoice.getId()).isEmpty()) {
566	            throw new InvoiceRejectedException(refusal);
567	        }
568	        invoice.reopen();
569	        return true;
570	    }
