572	    /**
573	     * Sends a draft invoice, issuing it today and making it due on the client's terms (or keeping a due
574	     * date set by hand), and records it in the audit; empty if no such invoice. An invoice already
575	     * sent, with no lines, whose discount needs a reason but has none, or whose due date set by hand is
576	     * before today, is refused.
577	     */
578	    @Transactional
579	    public Optional<Invoice> send(Long invoiceId) {
580	        Optional<Invoice> found = load(invoiceId);
581	        found.ifPresent(invoice -> {
582	            if (invoice.isVoid()) {
583	                throw new InvoiceRejectedException("A void invoice cannot be sent.");
584	            }
585	            if (!invoice.isDraft()) {
586	                throw new InvoiceRejectedException("This invoice has already been sent.");
587	            }
588	            if (invoice.getLines().isEmpty()) {
589	                throw new InvoiceRejectedException("Add at least one line before sending the invoice.");
590	            }
591	            if (invoice.isCreditNote()) {
592	                String refusal = creditNoteRefusal(invoice);
593	                if (refusal != null) {
594	                    throw new InvoiceRejectedException(refusal);
595	                }
596	                issue(invoice);
597	                return;
598	            }
599	            if (invoice.discountLacksReason()) {
600	                throw new InvoiceRejectedException(
601	                        "The discount is more than 20% of the subtotal; give it a reason before sending the invoice.");
602	            }
603	            if (invoice.dueDatePassedBy(today.date())) {
604	                throw new InvoiceRejectedException("The due date (" + invoice.getDueDate()
605	                        + ") is already past; set a later due date before sending the invoice.");
606	            }
607	            markSent(invoice);
608	        });
609	        return found;
610	    }
