612	    /**
613	     * Sends each of the client's drafts that has at least one line, lowest id first, as {@link #send}
614	     * would; drafts with no lines, whose discount needs a reason but has none, or whose due date set by
615	     * hand is already past, stay drafts.
616	     */
617	    @Transactional
618	    public void sendAllDrafts(Long clientId) {
619	        loadForClient(clientId).stream()
620	                .filter(invoice -> invoice.isDraft() && !invoice.getLines().isEmpty() && !invoice.discountLacksReason()
621	                        && !invoice.dueDatePassedBy(today.date()))
622	                .forEach(invoice -> {
623	                    if (!invoice.isCreditNote()) {
624	                        markSent(invoice);
625	                    } else if (creditNoteRefusal(invoice) == null) {
626	                        issue(invoice);
627	                    }
628	                });
629	    }
