631	    /**
632	     * Why the draft credit note cannot be issued, or null when it can: its original must be a sent
633	     * invoice (not void). On a plan it comes off the instalments to come, so the plan must have no
634	     * overdue instalment and the credit note cannot be more than the principal still owed before them.
635	     */
636	    private String creditNoteRefusal(Invoice note) {
637	        Invoice original = load(note.getCreditOf()).orElse(null);
638	        if (original == null || original.isDraft() || original.isVoid()) {
639	            return "The invoice this credits is not a sent invoice, so the credit note cannot be issued.";
640	        }
641	        String overCredit = overCreditRefusal(note, original);
642	        if (overCredit != null) {
643	            return overCredit;
644	        }
645	        if (original.hasPlan()) {
646	            BigDecimal rate = taxRate.percent();
647	            LocalDate on = today.date();
648	            withInterest(List.of(original));
649	            BigDecimal paid = paid(List.of(original)).get(original.getId());
650	            if (original.instalmentProgress(paid, rate, on).stream()
651	                    .anyMatch(p -> p.status() == Instalment.Status.OVERDUE)) {
652	                return "The plan of the invoice this credits has an overdue instalment, so the credit note cannot be issued.";
653	            }
654	            BigDecimal principal = original.principalToCome(on, rate);
655	            if (note.total(rate).compareTo(principal) > 0) {
656	                return "The credit note cannot be more than the " + original.currency().format(principal)
657	                        + " principal still owed on the plan's instalments to come.";
658	            }
659	        }
660	        return null;
661	    }
662	
663	    /**
664	     * Why the draft credit note would credit more of one of its original's lines than was invoiced,
665	     * counting the credit notes already issued against it, or null when it does not.
666	     */
667	    private String overCreditRefusal(Invoice note, Invoice original) {
668	        Map<Long, BigDecimal> inNote = creditedQty(List.of(note));
669	        if (inNote.isEmpty()) {
670	            return null;
671	        }
672	        Map<Long, BigDecimal> issued = creditedQty(loadForClient(original.getClientId()).stream()
673	                .filter(i -> i.getStatus() == InvoiceStatus.CREDIT_NOTE && original.getId().equals(i.getCreditOf()))
674	                .toList());
675	        for (InvoiceLine line : original.getLines()) {
676	            BigDecimal qty = inNote.get(line.getId());
677	            BigDecimal already = issued.getOrDefault(line.getId(), BigDecimal.ZERO);
678	            if (qty != null && qty.add(already).compareTo(line.getQty()) > 0) {
679	                return "The credit note cannot credit more of \"" + line.getDescription() + "\" than was invoiced: "
680	                        + line.getQty().stripTrailingZeros().toPlainString() + " invoiced, "
681	                        + already.stripTrailingZeros().toPlainString() + " already credited.";
682	            }
683	        }
684	        return null;
685	    }
686	
687	    /** The quantity the credit notes credit of each line they credit, by the id of the line credited. */
688	    private static Map<Long, BigDecimal> creditedQty(List<Invoice> notes) {
689	        Map<Long, BigDecimal> credited = new HashMap<>();
690	        notes.forEach(note -> note.getLines().stream().filter(l -> l.getCreditOfLine() != null)
691	                .forEach(l -> credited.merge(l.getCreditOfLine(), l.getQty(), BigDecimal::add)));
692	        return credited;
693	    }
694	
695	    /**
696	     * Issues the draft credit note today and records it in the audit: its grand total comes off what
697	     * its original still owes, then the retention it holds back; any rest is held on the client's
698	     * account as a credit payment dated today, also recorded in the audit.
699	     */
700	    private void issue(Invoice note) {
701	        BigDecimal rate = taxRate.percent();
702	        Invoice original = load(note.getCreditOf()).orElseThrow();
703	        // Read again what it has been credited: another credit note may just have been issued against it.
704	        entityManager.refresh(original);
705	        withInterest(List.of(original));
706	        BigDecimal total = note.total(rate);
707	        BigDecimal[] taken = original.creditTaken(total, paid(List.of(original)).get(original.getId()), rate);
708	        note.markIssued(today.date(), rate, taken[0], taken[1]);
709	        invoices.saveAndFlush(note);
