874	        if (left.signum() > 0) {
875	            throw new InvoiceRejectedException("The refund cannot be more than the client's unused credit of "
876	                    + currency.format(credit) + ".");
877	        }
878	        for (int i = 0; i < from.size(); i++) {
879	            Payment payment = from.get(i);
880	            payment.refund(parts.get(i));
881	            payments.saveAndFlush(payment);
882	            audit.record("CREDIT_REFUNDED payment=" + payment.getId() + " amount="
883	                    + parts.get(i).setScale(currency.scale(), RoundingMode.UNNECESSARY).toPlainString());
884	        }
885	        return Optional.of(clientId);
886	    }
