901	    /**
902	     * Voids a sent invoice paid nothing but credit used on it when it was sent, and records it in the
903	     * audit; that credit goes back on the client's account, unused again, each payment's part recorded
904	     * in the audit. Empty if no such invoice. A draft, an invoice already void, or one with a payment
905	     * recorded against it is refused.
906	     */
907	    @Transactional
908	    public Optional<Invoice> voidInvoice(Long invoiceId) {
909	        Optional<Invoice> found = load(invoiceId);
910	        found.ifPresent(invoice -> {
911	            if (invoice.isVoid()) {
912	                throw new InvoiceRejectedException("This invoice is already void.");
913	            }
914	            if (invoice.isDraft()) {
915	                throw new InvoiceRejectedException("A draft cannot be voided; only a sent invoice can.");
916	            }
917	            if (invoice.isCreditNote()) {
918	                throw new InvoiceRejectedException("An issued credit note cannot be voided.");
919	            }
920	            if (invoice.isWrittenOff()) {
921	                throw new InvoiceRejectedException("A written-off invoice cannot be voided.");
922	            }
923	            if (invoice.hasCreditNotesIssued()) {
924	                throw new InvoiceRejectedException("An invoice with an issued credit note cannot be voided.");
925	            }
926	            List<Payment> paidBy = payments.findForInvoice(invoice.getId());
927	            if (paidBy.stream().anyMatch(payment -> !payment.onlyCreditUsedOn(invoice.getId()))) {
928	                throw new InvoiceRejectedException("An invoice with a payment recorded against it cannot be voided.");
929	            }
930	            invoice.markVoid();
931	            invoices.saveAndFlush(invoice);
932	            for (Payment payment : paidBy) {
933	                BigDecimal returned = payment.returnCredit(invoice.getId());
934	                payments.saveAndFlush(payment);
935	                audit.record("CREDIT_RETURNED payment=" + payment.getId() + " amount="
936	                        + returned.setScale(invoice.scale(), RoundingMode.UNNECESSARY).toPlainString());
937	            }
938	            audit.record("INVOICE_VOIDED id=" + invoice.getId() + " number=" + invoice.number());
939	        });
940	        return found;
941	    }
