980	    /**
981	     * Records a payment of the amount on the date against a sent invoice that still has something
982	     * due, and records it in the audit; empty if no such invoice. The amount has already been
983	     * checked; what it pays beyond what is due is held on the client's account as credit. A draft, an
984	     * invoice already paid, or a date after today
985	     * or before the invoice's issue date is refused. The reference (null when none was quoted) has
986	     * already been checked; one that belongs to a different invoice is refused.
987	     */
988	    @Transactional
989	    public Optional<Invoice> recordPayment(Long invoiceId, BigDecimal paidAmount, Currency paidIn, LocalDate date,
990	            String reference) {
991	        Optional<Invoice> found = load(invoiceId);
992	        found.ifPresent(invoice -> {
993	            if (invoice.isDraft()) {
994	                throw new InvoiceRejectedException("Send the invoice before recording a payment.");
995	            }
996	            if (invoice.isVoid()) {
997	                throw new InvoiceRejectedException("A void invoice takes no payments.");
998	            }
999	            if (invoice.isCreditNote()) {
1000	                throw new InvoiceRejectedException("A credit note takes no payments.");
1001	            }
1002	            if (invoice.isWrittenOff()) {
1003	                throw new InvoiceRejectedException("A written-off invoice takes no more payments.");
1004	            }
1005	            BigDecimal amount = converted(paidAmount, paidIn, invoice.currency(), date);
1006	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
1007	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
1008	            if (due.signum() <= 0) {
1009	                throw new InvoiceRejectedException("This invoice has already been paid.");
1010	            }
1011	            LocalDate now = today.date();
1012	            BigDecimal early = BigDecimal.ZERO;
1013	            BigDecimal settle = date.isAfter(now) ? null : invoice.settleAmount(paidSoFar, taxRate.percent(), date);
1014	            if (settle != null && amount.compareTo(settle) >= 0) {
1015	                early = invoice.earlyDiscount(taxRate.percent());
1016	                invoice.takeEarlyDiscount(early);
1017	                due = settle;
1018	            }
1019	            BigDecimal saved = BigDecimal.ZERO;
1020	            BigDecimal payoff = date.isAfter(now) ? null : invoice.payoff(paidSoFar, taxRate.percent(), now);
1021	            if (payoff != null && amount.compareTo(payoff) >= 0) {
1022	                saved = due.subtract(payoff).max(BigDecimal.ZERO);
1023	                invoice.saveInterest(saved);
1024	                due = payoff;
1025	            }
1026	            BigDecimal applied = amount.min(due);
1027	            if (invoice.hasPlan() && invoice.isTooSmallPart(applied, paidSoFar, taxRate.percent())) {
1028	                throw new InvoiceRejectedException("A payment must be at least the "
1029	                        + invoice.currency().format(invoice.earliestUnpaid(paidSoFar, taxRate.percent()))
1030	                        + " still unpaid on the earliest unpaid instalment, unless it settles the plan.");
1031	            }
1032	            if (invoice.isTooSmallPart(applied, paidSoFar, taxRate.percent())) {
1033	                throw new InvoiceRejectedException("A part payment must be at least "
1034	                        + invoice.currency().format(invoice.minimumPart(taxRate.percent()))
1035	                        + " (10% of the total), unless it settles the invoice.");
1036	            }
1037	            if (date.isAfter(now)) {
1038	                throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
1039	            }
1040	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
1041	                throw new InvoiceRejectedException(
1042	                        "The payment date cannot be before the invoice's issue date (" + invoice.getIssueDate() + ").");
1043	            }
1044	            if (reference != null && !reference.equals(PaymentReference.of(invoice.getId()))) {
1045	                throw new InvoiceRejectedException(PaymentReference.grouped(reference)
1046	                        + " is the reference of a different invoice; this invoice's is "
1047	                        + PaymentReference.grouped(PaymentReference.of(invoice.getId())) + ".");
1048	            }
1049	            Payment payment = payments.saveAndFlush(Payment.against(invoice, amount, applied, date, reference)
1050	                    .paidIn(paidIn, paidAmount, invoice.currency()));
1051	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
1052	                    + applied.setScale(invoice.scale(), RoundingMode.UNNECESSARY).toPlainString());
1053	            if (invoice.currency() != Currency.USD) {
1054	                audit.record("FX_DIFFERENCE id=" + invoice.getId() + " payment=" + payment.getId() + " amount="
1055	                        + invoice.fxDifference(applied, date).toPlainString());
1056	            }
1057	            if (early.signum() > 0) {
1058	                invoices.saveAndFlush(invoice);
1059	                audit.record("EARLY_DISCOUNT id=" + invoice.getId() + " amount=" + early.toPlainString());
1060	            }
1061	            if (payoff != null && amount.compareTo(payoff) >= 0) {
1062	                invoices.saveAndFlush(invoice);
1063	                audit.record("PLAN_SETTLED id=" + invoice.getId() + " saved=" + saved.toPlainString());
1064	            }
1065	            recordWriteOff(invoice);
1066	            recordCreditHeld(payment);
1067	        });
1068	        return found;
1069	    }
