1071	    /**
1072	     * Records one payment of the amount on the date against the client's unpaid sent invoices: the overdue
1073	     * ones first, earliest due date first (lower id first on the same due date), then the rest from the
1074	     * largest amount due to the smallest (lower id first on the same amount), paying each off in full
1075	     * before the next.
1076	     * What it pays beyond everything the client owes is held on the client's account as credit; the
1077	     * rest is checked and recorded as a split payment over the invoices it reaches.
1078	     * References (empty when none, each already checked) instead limit the payment to the client's
1079	     * invoices with those references, applied in the same order; one that is not the reference of any
1080	     * of the client's invoices is refused; what is paid beyond what those invoices owe together is held
1081	     * as credit.
1082	     * A reference may state the amount it gets: that amount goes to that invoice, and only the rest of
1083	     * the payment is applied, in the same order, to the references without one. The amounts stated must
1084	     * each be more than zero and together no more than the payment; each must be no more than its
1085	     * invoice has due and at least its minimum part payment (both checked with the other parts).
1086	     * The payment keeps the reference of the first invoice it reaches.
1087	     */
1088	    @Transactional
1089	    public Payment recordAutoPayment(Long clientId, BigDecimal paidAmount, Currency paidIn, LocalDate date,
1090	            List<QuotedReference> references) {
1091	        Currency currency = currencyOf(clientId);
1092	        BigDecimal amount = converted(paidAmount, paidIn, currency, date);
1093	        List<Invoice> ofClient = loadForClient(clientId);
1094	        List<Invoice> candidates = ofClient;
1095	        List<PaymentAllocation> parts = new ArrayList<>();
1096	        BigDecimal left = amount;
1097	        if (!references.isEmpty()) {
1098	            Set<Long> named = new HashSet<>();
1099	            Set<Long> stated = new HashSet<>();
1100	            for (QuotedReference quoted : references) {
1101	                String reference = quoted.reference();
1102	                Invoice invoice = ofClient.stream()
1103	                        .filter(i -> reference.equals(PaymentReference.of(i.getId())))
1104	                        .findFirst()
1105	                        .orElseThrow(() -> new InvoiceRejectedException(PaymentReference.grouped(reference)
1106	                                + " is not the reference of any of this client's invoices."));
1107	                String number = InvoiceNumber.of(invoice.getId());
1108	                if (invoice.isDraft()) {
1109	                    throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
1110	                }
1111	                if (invoice.isVoid()) {
1112	                    throw new InvoiceRejectedException(number + " is void and takes no payments.");
1113	                }
1114	                if (invoice.isCreditNote()) {
1115	                    throw new InvoiceRejectedException(invoice.number() + " is a credit note and takes no payments.");
1116	                }
1117	                if (quoted.amount() == null) {
1118	                    named.add(invoice.getId());
1119	                    continue;
1120	                }
1121	                if (quoted.amount().signum() <= 0) {
1122	                    throw new InvoiceRejectedException("The amount for " + number + " must be more than zero.");
1123	                }
1124	                if (!stated.add(invoice.getId())) {
1125	                    throw new InvoiceRejectedException("State only one amount for " + number + ".");
1126	                }
1127	                parts.add(new PaymentAllocation(invoice.getId(), quoted.amount()));
1128	                left = left.subtract(quoted.amount());
1129	            }
1130	            if (left.signum() < 0) {
1131	                BigDecimal sum = amount.subtract(left);
1132	                throw new InvoiceRejectedException("The amounts stated for the invoices add up to "
1133	                        + currency.format(sum) + ", more than the " + currency.format(amount) + " paid.");
1134	            }
1135	            named.removeAll(stated);
1136	            candidates = ofClient.stream().filter(i -> named.contains(i.getId())).toList();
1137	        }
1138	        Map<Long, BigDecimal> dues = new HashMap<>();
1139	        List<Invoice> sent = inPaymentOrder(candidates, dues);
1140	        for (Invoice invoice : sent) {
1141	            BigDecimal due = dues.get(invoice.getId());
1142	            if (due.signum() <= 0) {
1143	                continue;
1144	            }
1145	            if (left.signum() > 0) {
1146	                BigDecimal part = left.min(due);
1147	                parts.add(new PaymentAllocation(invoice.getId(), part));
1148	                left = left.subtract(part);
1149	            }
1150	        }
1151	        if (parts.isEmpty()) {
1152	            throw new InvoiceRejectedException(references.isEmpty() ? "The client has no unpaid invoices to pay."
1153	                    : "Those invoices have already been paid.");
1154	        }
1155	        String reference = references.isEmpty() ? null : PaymentReference.of(parts.get(0).getInvoiceId());
1156	        return recordSpread(clientId, amount, paidAmount, paidIn, date, reference, parts);
1157	    }
