1159	    /**
1160	     * The sent invoices among these (not drafts, void invoices or credit notes) in the payment order:
1161	     * the overdue ones first, earliest due date first, then the rest from the largest amount due to the
1162	     * smallest; lower id first on a tie. Fills in what each has due.
1163	     */
1164	    private List<Invoice> inPaymentOrder(List<Invoice> candidates, Map<Long, BigDecimal> dues) {
1165	        List<Invoice> unordered = candidates.stream()
1166	                .filter(i -> !i.isDraft() && !i.isVoid() && !i.isCreditNote())
1167	                .toList();
1168	        Map<Long, BigDecimal> paid = paid(unordered);
1169	        LocalDate now = today.date();
1170	        Set<Long> overdue = new HashSet<>();
1171	        for (Invoice invoice : unordered) {
1172	            BigDecimal invoicePaid = paid.get(invoice.getId());
1173	            dues.put(invoice.getId(), invoice.amountDue(invoicePaid, taxRate.percent()));
1174	            if (invoice.statusWhenPaid(invoicePaid, taxRate.percent(), now) == InvoiceStatus.OVERDUE) {
1175	                overdue.add(invoice.getId());
1176	            }
1177	        }
1178	        // Overdue first, oldest due date first; then the rest, largest amount due first; lower id on a tie.
1179	        Comparator<Invoice> byPriority = Comparator.<Invoice, Boolean>comparing(i -> !overdue.contains(i.getId()))
1180	                .thenComparing(i -> overdue.contains(i.getId()) ? i.getDueDate() : null,
1181	                        Comparator.nullsLast(Comparator.naturalOrder()))
1182	                .thenComparing(i -> overdue.contains(i.getId()) ? BigDecimal.ZERO : dues.get(i.getId()),
1183	                        Comparator.reverseOrder())
1184	                .thenComparing(Invoice::getId);
1185	        return unordered.stream().sorted(byPriority).toList();
1186	    }
