1188	    /**
1189	     * Uses the client's unused credit now on what they owe: the oldest payment's credit first (lower id
1190	     * first on the same date), never a deposit held for one of the client's drafts, spread over their
1191	     * sent invoices in the payment order (see {@link #inPaymentOrder}), each paid off before the next;
1192	     * each part applied today and recorded in the audit. Empty if no such client. Refused when the
1193	     * client has no credit to use or owes nothing.
1194	     */
1195	    @Transactional
1196	    public Optional<Long> applyCreditNow(Long clientId) {
1197	        Optional<Client> client = clients.findById(clientId);
1198	        if (client.isEmpty()) {
1199	            return Optional.empty();
1200	        }
1201	        Map<String, Long> drafts = draftsByReference(clientId);
1202	        List<Payment> usable = payments.findForClient(clientId).stream()
1203	                .filter(p -> heldFor(p, drafts) == null && p.credit().signum() > 0)
1204	                .toList();
1205	        if (usable.isEmpty()) {
1206	            throw new InvoiceRejectedException("The client has no unused credit to apply.");
1207	        }
1208	        Map<Long, BigDecimal> dues = new HashMap<>();
1209	        List<Invoice> owing = inPaymentOrder(loadForClient(clientId), dues).stream()
1210	                .filter(i -> dues.get(i.getId()).signum() > 0)
1211	                .toList();
1212	        if (owing.isEmpty()) {
1213	            throw new InvoiceRejectedException("The client owes nothing to apply credit to.");
1214	        }
1215	        LocalDate now = today.date();
1216	        Set<Invoice> reached = new LinkedHashSet<>();
1217	        Iterator<Payment> from = usable.iterator();
1218	        Payment payment = from.next();
1219	        BigDecimal credit = payment.credit();
1220	        for (Invoice invoice : owing) {
1221	            BigDecimal due = dues.get(invoice.getId());
1222	            while (due.signum() > 0 && credit != null) {
1223	                BigDecimal part = credit.min(due);
1224	                payment.apply(invoice.getId(), part, now);
1225	                payments.saveAndFlush(payment);
1226	                audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
1227	                        + part.setScale(invoice.scale(), RoundingMode.UNNECESSARY).toPlainString());
1228	                reached.add(invoice);
1229	                due = due.subtract(part);
1230	                credit = credit.subtract(part);
1231	                if (credit.signum() <= 0) {
1232	                    payment = from.hasNext() ? from.next() : null;
1233	                    credit = payment == null ? null : payment.credit();
1234	                }
1235	            }
1236	            if (credit == null) {
1237	                break;
1238	            }
1239	        }
1240	        reached.forEach(this::recordWriteOff);
1241	        return Optional.of(clientId);
1242	    }
