1244	    /**
1245	     * Records one payment of the amount on the date spread over several of the client's invoices, and
1246	     * records each part in the audit. The amounts have already been checked to be more than zero; they
1247	     * must add up to no more than the payment: the rest is
1248	     * held on the client's account as credit and recorded in the audit. Each must go to a different
1249	     * sent invoice of the client and be no more than what it still has due. The date must be no later
1250	     * than today nor before any of the invoices' issue dates. The reference (null when none) has
1251	     * already been checked; it must be the reference of one of the invoices.
1252	     */
1253	    private Payment recordSpread(Long clientId, BigDecimal amount, BigDecimal paidAmount, Currency paidIn,
1254	            LocalDate date, String reference, List<PaymentAllocation> parts) {
1255	        if (parts.isEmpty()) {
1256	            throw new InvoiceRejectedException("Enter how much of the payment goes to each invoice.");
1257	        }
1258	        Currency currency = currencyOf(clientId);
1259	        requireWhole(currency, amount, "The amount");
1260	        for (PaymentAllocation part : parts) {
1261	            requireWhole(currency, part.getAmount(), "Each invoice's part");
1262	        }
1263	        BigDecimal sum = parts.stream().map(PaymentAllocation::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
1264	        if (sum.compareTo(amount) > 0) {
1265	            throw new InvoiceRejectedException("The amounts for the invoices add up to "
1266	                    + currency.format(sum) + ", not the " + currency.format(amount) + " paid.");
1267	        }
1268	        LocalDate now = today.date();
1269	        if (date.isAfter(now)) {
1270	            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
1271	        }
1272	        Set<Long> seen = new HashSet<>();
1273	        List<Invoice> spreadOver = new ArrayList<>();
1274	        for (PaymentAllocation part : parts) {
1275	            if (!seen.add(part.getInvoiceId())) {
1276	                throw new InvoiceRejectedException("Each invoice can take only one part of the payment.");
1277	            }
1278	            Invoice invoice = load(part.getInvoiceId())
1279	                    .filter(i -> i.getClientId().equals(clientId))
1280	                    .orElseThrow(() -> new InvoiceRejectedException("A part of the payment goes to an invoice of another client."));
1281	            String number = InvoiceNumber.of(invoice.getId());
1282	            if (invoice.isDraft()) {
1283	                throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
1284	            }
1285	            if (invoice.isVoid()) {
1286	                throw new InvoiceRejectedException(number + " is void and takes no payments.");
1287	            }
1288	            if (invoice.isCreditNote()) {
1289	                throw new InvoiceRejectedException(invoice.number() + " is a credit note and takes no payments.");
1290	            }
1291	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
1292	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
1293	            if (part.getAmount().compareTo(due) > 0) {
1294	                throw new InvoiceRejectedException("The " + currency.format(part.getAmount()) + " for "
1295	                        + number + " is more than the " + currency.format(due) + " it has due.");
1296	            }
1297	            if (invoice.hasPlan() && invoice.isTooSmallPart(part.getAmount(), paidSoFar, taxRate.percent())) {
1298	                throw new InvoiceRejectedException("The " + currency.format(part.getAmount()) + " for "
1299	                        + number + " is less than the " + currency.format(invoice.earliestUnpaid(paidSoFar, taxRate.percent()))
1300	                        + " still unpaid on its earliest unpaid instalment, unless it settles the plan.");
1301	            }
1302	            if (invoice.isTooSmallPart(part.getAmount(), paidSoFar, taxRate.percent())) {
1303	                throw new InvoiceRejectedException("The " + currency.format(part.getAmount()) + " for "
1304	                        + number + " is less than " + currency.format(invoice.minimumPart(taxRate.percent()))
1305	                        + " (10% of its total), unless it settles the invoice.");
1306	            }
1307	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
1308	                throw new InvoiceRejectedException("The payment date cannot be before the issue date of " + number
1309	                        + " (" + invoice.getIssueDate() + ").");
1310	            }
1311	            spreadOver.add(invoice);
1312	        }
1313	        if (reference != null && spreadOver.stream().noneMatch(i -> reference.equals(PaymentReference.of(i.getId())))) {
1314	            throw new InvoiceRejectedException(PaymentReference.grouped(reference)
1315	                    + " is not the reference of any of the invoices being paid.");
1316	        }
1317	        Payment payment = payments.saveAndFlush(Payment.split(clientId, amount, date, reference, parts)
1318	                .paidIn(paidIn, paidAmount, currency));
1319	        for (PaymentAllocation part : parts) {
1320	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + part.getInvoiceId() + " amount="
1321	                    + part.getAmount().setScale(currency.scale(), RoundingMode.UNNECESSARY).toPlainString());
1322	        }
1323	        if (currency != Currency.USD) {
1324	            for (Invoice invoice : spreadOver) {
1325	                audit.record("FX_DIFFERENCE id=" + invoice.getId() + " payment=" + payment.getId() + " amount="
1326	                        + invoice.fxDifference(payment.amountTo(invoice.getId()), date).toPlainString());
